window.ATLAS = {"modules": [{"id": "foundations", "title": "Core CS fundamentals", "description": "Build the mental models everything else rests on.", "icon": "⌘"}, {"id": "networking", "title": "Networking & the web", "description": "Follow a packet from your browser to the backend.", "icon": "↗"}, {"id": "runtimes", "title": "Languages & runtimes", "description": "Understand the engine behind each request.", "icon": "⚙"}, {"id": "apis", "title": "APIs & real-time", "description": "Design interfaces that are a pleasure to use.", "icon": "⇄"}, {"id": "databases", "title": "Databases & storage", "description": "Keep data correct, find it fast, and scale it.", "icon": "▤"}, {"id": "caching", "title": "Caching & memory", "description": "Make the fast path fast, without losing correctness.", "icon": "ϟ"}, {"id": "security", "title": "Authentication & security", "description": "Build trust into every layer of the system.", "icon": "◇"}, {"id": "messaging", "title": "Queues & Kafka", "description": "Move work out of the request path.", "icon": "≋"}, {"id": "resilience", "title": "Resilience & scraping", "description": "Design for the day dependencies fail.", "icon": "↻"}, {"id": "performance", "title": "Concurrency & performance", "description": "Measure, explain, and improve your bottlenecks.", "icon": "◷"}, {"id": "architecture", "title": "Architecture & integrity", "description": "Draw boundaries and protect business invariants.", "icon": "⬡"}, {"id": "systems", "title": "System design toolkit", "description": "Turn scale and trade-offs into concrete decisions.", "icon": "▦"}, {"id": "designs", "title": "System design practice", "description": "Work through nineteen real design problems.", "icon": "✎"}, {"id": "lld", "title": "Low-level design", "description": "Turn requirements into small, testable objects.", "icon": "⊞"}, {"id": "devops", "title": "DevOps & cloud", "description": "Ship, observe, and safely change your system.", "icon": "☁"}, {"id": "testing", "title": "Testing & observability", "description": "Know what works and understand what broke.", "icon": "◎"}, {"id": "projects", "title": "Build it yourself", "description": "Apply the course in seven portfolio projects.", "icon": "⚑"}], "lessons": [{"id": "arrays-strings-linked-lists", "module": "foundations", "title": "Arrays, strings & linked lists", "level": "Foundation", "concept": "An array stores elements in indexed order. Access by index is O(1), but inserting at the beginning normally shifts O(n) elements. A dynamic array grows by allocating a larger buffer and copying, which makes append amortized O(1). Strings represent text; an index may refer to a byte, code unit, or character depending on the language. A linked list stores values in separately allocated nodes joined by pointers.", "deep": "Choose by the operations you need. Arrays have good cache locality and fast random access. Lists can splice a node in O(1) when its predecessor is already known, but locating that position still takes O(n). A singly linked list points forward; a doubly linked list also points backward. Immutable strings often allocate a new object when changed, so repeated concatenation may require a builder.", "examples": ["Playlist: an array lets you jump straight to track 12; inserting a new first track shifts existing positions.", "LRU cache: a doubly linked list moves a known item to the front; a hash map supplies the node reference."], "nodes": ["Array [A,B,C]", "Insert X at 1", "Shift suffix", "Result [A,X,B,C]"], "steps": ["Read index 1 directly: B. No traversal is needed.", "Reserve a slot for X, keeping the prefix A unchanged.", "Move C then B one position right, avoiding overwrite.", "Write X at index 1. Two old elements moved: insertion is linear."], "pitfall": "O(1) list insertion assumes you already have the insertion location. Text length and byte length are not always equal.", "minutes": 12, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Arrays%2C%20strings%20%26%20linked%20lists%20explained%20computer%20science", "takeaway": "O(1) list insertion assumes you already have the insertion location. Text length and byte length are not always equal."}, {"id": "stacks-queues-deques", "module": "foundations", "title": "Stacks, queues & deques", "level": "Foundation", "concept": "A stack removes the most recently added item: last in, first out. A queue removes the oldest item: first in, first out. A deque allows insertion and removal at both ends. These are interfaces; a ring buffer, linked nodes, or a dynamic array can implement them. Selecting the right interface often makes an algorithm simpler than choosing a clever implementation.", "deep": "Stacks model nested work such as function calls and balanced brackets. Queues model fair arrival order and breadth-first exploration. Deques support sliding windows and work stealing. A bounded queue adds a capacity limit, requiring a choice between blocking, rejecting, or dropping work. Always specify empty behavior, capacity, and whether operations are safe across threads.", "examples": ["Undo: type A, then B; pop B first to reverse the latest change.", "Checkout line: customers A then B join; dequeue A first. A priority queue would use a different ordering."], "nodes": ["Enqueue A", "Enqueue B", "Front = A", "Dequeue A"], "steps": ["The empty FIFO queue receives A: [A].", "Append B at the tail: [A,B].", "Peek reads A without removing it.", "Remove A, leaving [B]. A stack would instead remove B."], "pitfall": "A queue data structure alone does not provide durable delivery or distributed message guarantees.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Stacks%2C%20queues%20%26%20deques%20explained%20computer%20science", "takeaway": "A queue data structure alone does not provide durable delivery or distributed message guarantees."}, {"id": "hash-maps-sets-collision-handling", "module": "foundations", "title": "Hash maps, sets & collision handling", "level": "Foundation", "concept": "A hash map turns a key into a bucket index, then finds the matching key in that bucket. A set uses the same idea to store membership without an associated value. Good hash distribution makes lookup, insertion, and deletion expected O(1), not guaranteed O(1). Collisions happen when different keys map to the same bucket and must be resolved without confusing the keys.", "deep": "Separate chaining stores multiple entries per bucket; open addressing probes other slots. Resizing keeps the load factor under control but costs O(n) on that operation. Equality and hashing must agree: equal keys need equal hashes. Do not mutate fields that define a key while it is stored. Hash maps generally do not imply sorted order.", "examples": ["Deduplication: put each visitor ID in a set; a second occurrence does not add a new unique visitor.", "User lookup: map user ID 42 to a profile instead of scanning every profile."], "nodes": ["Key alice", "Hash bucket 2", "Compare keys", "Return value"], "steps": ["Compute a deterministic hash for alice.", "Reduce the hash to bucket 2. Another key may already be there.", "Compare the complete keys within the collision chain.", "Return only the value whose key equals alice; matching a bucket is insufficient."], "pitfall": "Hashing is not encryption. Poor or adversarial hashing can degrade lookup performance.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Hash%20maps%2C%20sets%20%26%20collision%20handling%20explained%20computer%20science", "takeaway": "Hashing is not encryption. Poor or adversarial hashing can degrade lookup performance."}, {"id": "trees-bsts-avl-trees-heaps", "module": "foundations", "title": "Trees, BSTs, AVL trees & heaps", "level": "Foundation", "concept": "A tree connects nodes without cycles. A binary tree has at most two children per node; a binary search tree additionally orders smaller keys to the left and larger keys to the right. Search cost is proportional to height. An unbalanced BST may become a chain with O(n) searches. AVL trees use rotations to keep subtree heights within one, preserving O(log n) lookup and updates.", "deep": "A heap enforces a different rule: the parent has priority over its children. A min-heap gives O(1) access to the smallest item and O(log n) insertion or removal, but arbitrary search remains O(n). A heap is not a sorted array. Use ordered trees for range queries and heaps for repeatedly selecting the next highest-priority item.", "examples": ["Scheduler: put jobs into a min-heap by deadline; pop the earliest deadline next.", "BST lookup: for key 7 at root 10, descend left; at 5, descend right."], "nodes": ["Root 10", "Left child 5", "Right child 7", "Found 7"], "steps": ["Compare target 7 with root 10: 7 is smaller.", "Move left to 5; 7 is larger than 5.", "Move right to 7, following the BST ordering.", "Return the node after three comparisons. Balance controls path length."], "pitfall": "The BST ordering rule and the heap priority rule are different invariants.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Trees%2C%20BSTs%2C%20AVL%20trees%20%26%20heaps%20explained%20computer%20science", "takeaway": "The BST ordering rule and the heap priority rule are different invariants."}, {"id": "tries-prefix-search", "module": "foundations", "title": "Tries & prefix search", "level": "Foundation", "concept": "A trie stores keys along paths of symbols. A path for cat shares its c and a nodes with car. Lookup is O(L) in the key length rather than O(log n) in the number of keys, under constant-time child access. A terminal marker distinguishes a complete word from a prefix that merely leads to other words.", "deep": "For autocomplete, walk to the prefix node and enumerate descendants, usually with a limit or ranking. Tries can use much more memory than a hash map because each node may contain many child pointers. Compressed radix trees merge one-child paths. Unicode normalization and case folding should be deliberate parts of the indexing pipeline.", "examples": ["Autocomplete: entering ca reaches one subtree containing car, cat, and cake.", "Routing: a prefix structure can locate the longest matching network prefix rather than only exact matches."], "nodes": ["Root", "c node", "a node", "t terminal"], "steps": ["Start at the root for lookup cat.", "Follow edge c; fail immediately if the edge is absent.", "Follow edge a; this is a prefix, not necessarily a complete key.", "Follow t and inspect the terminal flag to confirm cat exists."], "pitfall": "Prefix lookup is fast, but returning every completion can still take time proportional to the output size.", "minutes": 10, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Tries%20%26%20prefix%20search%20explained%20computer%20science", "takeaway": "Prefix lookup is fast, but returning every completion can still take time proportional to the output size."}, {"id": "sorting-binary-search", "module": "foundations", "title": "Sorting & binary search", "level": "Foundation", "concept": "Sorting establishes an ordering so later operations can exploit structure. Merge sort takes O(n log n) time and commonly O(n) extra space. Quicksort is typically O(n log n), with O(n²) worst-case behavior unless mitigated. Insertion sort is O(n²) but useful for small or nearly sorted inputs. A stable sort preserves the original order of equal keys.", "deep": "Binary search repeatedly halves a sorted search range, taking O(log n) comparisons. Define an invariant, such as a half-open interval [lo, hi), to avoid off-by-one bugs. Lower bound finds the first element not less than a target and handles duplicates predictably. Binary search also applies to monotone answers, such as the smallest capacity that satisfies a scheduling constraint.", "examples": ["Search 7 in [1,3,5,7,9]: compare 5, discard the left half, then find 7.", "Sort invoices by date using a stable sort so invoices with the same date retain their earlier reference order."], "nodes": ["[1,3,5,7,9]", "Mid = 5", "Range [7,9]", "Found 7"], "steps": ["The array is sorted, satisfying the search prerequisite.", "Compare target 7 with midpoint 5.", "Discard values through 5; only the right interval can contain 7.", "Compare with 7 and finish. No full scan was required."], "pitfall": "Binary search requires sorted data or another monotone predicate; it does not work on an arbitrary array.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Sorting%20%26%20binary%20search%20explained%20computer%20science", "takeaway": "Binary search requires sorted data or another monotone predicate; it does not work on an arbitrary array."}, {"id": "two-pointers-sliding-windows", "module": "foundations", "title": "Two pointers & sliding windows", "level": "Foundation", "concept": "Two pointers maintain positions that move through an array or string while preserving an invariant. In a sorted array, one pointer at each end can find a target sum in O(n). A sliding window tracks a contiguous interval and updates a running state as the right edge grows and the left edge shrinks. Each index often moves at most once, giving O(n) total work.", "deep": "The window rule is the important part. For nonnegative numbers, a sum that is too large can be reduced by moving the left edge. Negative values can break this monotonicity and require prefix sums or another structure. For text windows, a frequency map tracks repeated symbols. Specify whether the goal is fixed width, longest valid interval, or shortest satisfying interval.", "examples": ["Target sum 10 in [1,2,4,8]: 1+8 is 9, so move left forward; 2+8 gives 10.", "Maximum sum of width 3 in [2,1,5,1]: first sum is 8; subtract 2 and add 1 for the next sum, 7."], "nodes": ["Window [2,1,5]", "Sum = 8", "Slide right", "Window [1,5,1]"], "steps": ["Create the first width-three window.", "Store sum 8 as the best so far.", "Remove outgoing 2 and add incoming 1; avoid recomputing every element.", "New sum is 7, so the previous window remains best."], "pitfall": "Not every subarray problem admits a shrinking window, especially when negative numbers break the chosen invariant.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Two%20pointers%20%26%20sliding%20windows%20explained%20computer%20science", "takeaway": "Not every subarray problem admits a shrinking window, especially when negative numbers break the chosen invariant."}, {"id": "recursion-backtracking-dynamic-programming", "module": "foundations", "title": "Recursion, backtracking & dynamic programming", "level": "Foundation", "concept": "Recursion solves a problem through smaller instances and a base case. Backtracking explores choices, then undoes a choice when returning so other branches start from a clean state. Dynamic programming reuses answers to overlapping subproblems; memoization caches recursive results and tabulation fills a table in dependency order. The state must contain every fact needed to determine the remaining answer.", "deep": "Begin by writing the state, transition, and base case. Fibonacci has O(n) distinct states even though naive recursion makes exponentially many calls. For 0/1 knapsack, state includes item position and remaining capacity; omitting either changes the problem. Reconstruction may require saving parent choices. Recursion depth and table size are real memory costs, not just implementation details.", "examples": ["Stair climbing: ways(4)=ways(3)+ways(2). Cache ways(2) so both branches share its result.", "Subsets of [A,B]: choose A or skip A, then choose B or skip B, restoring the current subset after each branch."], "nodes": ["ways(4)", "ways(3)", "Cached ways(2)", "Result 5"], "steps": ["Base cases: ways(0)=1 and ways(1)=1.", "Compute ways(3) from smaller states.", "Reuse ways(2)=2 rather than expanding it again.", "ways(3)=3, so ways(4)=3+2=5."], "pitfall": "Memoization only works when equal states imply equal answers. Hidden mutable inputs can invalidate the cache.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Recursion%2C%20backtracking%20%26%20dynamic%20programming%20explained%20computer%20science", "takeaway": "Memoization only works when equal states imply equal answers. Hidden mutable inputs can invalidate the cache."}, {"id": "greedy-algorithms-correctness", "module": "foundations", "title": "Greedy algorithms & correctness", "level": "Foundation", "concept": "A greedy algorithm commits to a locally appealing choice without revisiting it. It is correct only when the problem has a structure that makes such commitments safe. An exchange argument shows that an optimal solution can be transformed to include the greedy choice without worsening its result. Greedy algorithms are often fast because they avoid exploring an exponential choice tree.", "deep": "Interval scheduling chooses the earliest finishing compatible interval to maximize the number selected. Sorting by earliest start instead can fail. Coin change is greedy for some currency systems but not all: denominations [1,3,4] and target 6 defeat largest-first. Always separate an intuitive heuristic from a proven algorithm, and actively test a small counterexample.", "examples": ["Intervals [1,3], [2,5], [3,4]: choose [1,3], then [3,4] for two compatible meetings.", "Coins [1,3,4], target 6: greedy gives 4+1+1; optimal is 3+3."], "nodes": ["All meetings", "Earliest finish", "Remove overlaps", "Select next"], "steps": ["Sort candidate intervals by finish time.", "Choose [1,3] because it leaves the most remaining room.", "Discard [2,5], which overlaps the chosen interval.", "Choose [3,4]; the resulting schedule contains two meetings."], "pitfall": "A fast greedy solution needs a proof or a clearly stated approximation goal.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Greedy%20algorithms%20%26%20correctness%20explained%20computer%20science", "takeaway": "A fast greedy solution needs a proof or a clearly stated approximation goal."}, {"id": "graphs-bfs-dfs", "module": "foundations", "title": "Graphs, BFS & DFS", "level": "Foundation", "concept": "A graph represents vertices and edges. Edges may be directed or undirected, weighted or unweighted. Adjacency lists use O(V+E) space and work well for sparse graphs; matrices use O(V²) space and offer direct edge checks. BFS uses a queue to explore by distance layers. DFS follows one branch deeply before returning and is useful for components, cycle detection, and dependency reasoning.", "deep": "With adjacency lists, both traversals take O(V+E). Mark visited vertices at discovery to avoid repeated enqueues. BFS finds shortest paths in an unweighted graph because every edge has equal cost. DFS does not generally do so. For a directed cycle detector, distinguish unseen, active, and finished nodes; an edge to an active node indicates a cycle.", "examples": ["Social graph: BFS finds the minimum number of friendship hops from A to D.", "Maze exploration: DFS follows a corridor, backtracks at a wall, and explores the next branch."], "nodes": ["Queue [A]", "Visit B,C", "Queue [B,C]", "Discover D"], "steps": ["Mark A visited and enqueue it at distance 0.", "Remove A and enqueue its unseen neighbors B and C at distance 1.", "Process B before moving to the next distance layer.", "If B reaches D, record parent B and distance 2; reconstruct A→B→D."], "pitfall": "BFS shortest-path guarantees require equal edge weights. Weighted graphs need an appropriate weighted-path algorithm.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Graphs%2C%20BFS%20%26%20DFS%20explained%20computer%20science", "takeaway": "BFS shortest-path guarantees require equal edge weights. Weighted graphs need an appropriate weighted-path algorithm."}, {"id": "dijkstra-topological-sort-union-find", "module": "foundations", "title": "Dijkstra, topological sort & union-find", "level": "Intermediate", "concept": "Dijkstra finds shortest paths with nonnegative edge weights by repeatedly finalizing the smallest tentative distance using a priority queue. Topological sorting orders a directed acyclic graph so prerequisites precede dependents; Kahn’s algorithm removes zero-indegree nodes. Union-find tracks disjoint sets with a representative root and supports efficient connectivity checks and merges.", "deep": "Dijkstra with a binary heap takes O((V+E) log V); skip stale heap entries after a better distance is found. Topological sort takes O(V+E); if not all vertices are emitted, there is a cycle. Union by rank or size plus path compression makes union-find operations amortized near constant. Union-find is useful for Kruskal’s minimum spanning tree, but does not give shortest paths.", "examples": ["Weighted roads: A→B costs 2, A→C costs 9, B→C costs 3. Dijkstra improves C from 9 to 5.", "Build dependencies: compile library before app. Kahn’s algorithm rejects a cyclic app↔library dependency."], "nodes": ["Dist A=0", "Relax B=2,C=9", "Pop B=2", "Improve C=5"], "steps": ["Initialize all distances to infinity except A.", "Visit A and place B and C in the min-heap.", "Finalize B because it has the smallest tentative distance.", "Relax B→C, replacing 9 with 2+3=5. Ignore the stale 9 entry later."], "pitfall": "Dijkstra is not valid with negative weights. Union-find handles connectivity rather than arbitrary deletion or path queries.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Dijkstra%2C%20topological%20sort%20%26%20union-find%20explained%20computer%20science", "takeaway": "Dijkstra is not valid with negative weights. Union-find handles connectivity rather than arbitrary deletion or path queries."}, {"id": "time-space-complexity", "module": "foundations", "title": "Time & space complexity", "level": "Foundation", "concept": "Complexity describes how resource use grows with input size. O(1), O(log n), O(n), O(n log n), and O(n²) are useful growth classes, not stopwatch measurements. State which input size you mean and whether the claim is worst-case, expected, or amortized. Space complexity includes auxiliary structures and the recursion call stack, not just explicit arrays.", "deep": "A nested loop is not automatically quadratic: two pointers that each move forward at most n times still take O(n). Conversely, an apparently single loop may call an O(n) operation each iteration. Constants, cache misses, allocation, and network costs matter in practice. Use complexity to reject unscalable designs, then benchmark realistic inputs before choosing between candidates in the same growth class.", "examples": ["For n=1,000, a full pairwise comparison performs about one million checks; doubling n roughly quadruples that count.", "Binary search needs at most about 20 comparisons for one million sorted items, versus up to one million for a scan."], "nodes": ["n = 10", "Linear = 10", "Quadratic = 100", "Double n"], "steps": ["Set the input size to 10.", "A linear scan visits each of 10 items once.", "A double full loop considers 10×10 pairs.", "At n=20, linear work is 20 while quadratic work is 400: growth rates differ."], "pitfall": "Big-O is not a measured latency, and dropping constants does not make constants irrelevant to production.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Time%20%26%20space%20complexity%20explained%20computer%20science", "takeaway": "Big-O is not a measured latency, and dropping constants does not make constants irrelevant to production."}, {"id": "processes-threads-cpu-scheduling", "module": "foundations", "title": "Processes, threads & CPU scheduling", "level": "Foundation", "concept": "A process owns an address space and resources; its threads share that address space but have separate stacks and register state. A process can fail without directly corrupting another process’s private memory. Threads communicate easily through shared memory but need synchronization. A context switch saves one execution context and restores another; costs depend on caches, address-space changes, and operating-system details.", "deep": "The scheduler chooses runnable work, using policies such as round robin, priorities, and fairness mechanisms. CPU-bound tasks keep cores busy; I/O-bound tasks often sleep awaiting external completion. More threads than cores can improve overlap during waiting, but cannot create more CPU capacity. Track runnable tasks, not just total thread count, and distinguish concurrency from simultaneous parallel execution.", "examples": ["A browser can isolate tabs in processes so a crashing tab does not directly overwrite another tab’s heap.", "Two server threads share a connection pool but each keeps its own current request stack."], "nodes": ["Thread A runs", "Timer interrupt", "Save A state", "Thread B runs"], "steps": ["A uses the CPU while B is runnable.", "The scheduler receives an opportunity to reschedule.", "Save A’s registers and stack position; its process memory remains allocated.", "Restore B’s context and let it run. Work is interleaved on one core."], "pitfall": "A context switch is not free, and adding threads does not guarantee higher throughput.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Processes%2C%20threads%20%26%20CPU%20scheduling%20explained%20computer%20science", "takeaway": "A context switch is not free, and adding threads does not guarantee higher throughput."}, {"id": "race-conditions-mutexes-semaphores-deadlock", "module": "foundations", "title": "Race conditions, mutexes, semaphores & deadlock", "level": "Foundation", "concept": "A race condition occurs when correctness depends on an uncontrolled ordering of concurrent operations. A mutex permits one owner in a critical section. A semaphore manages a count of available permits and can admit several users. Neither automatically makes a whole workflow correct: the protected region must include the read, decision, and write that form an invariant.", "deep": "Deadlock can arise when tasks hold resources while waiting in a cycle. A consistent global lock ordering prevents many such cycles; timeouts and deadlock detection provide recovery. An atomic increment protects one operation, not an arbitrary multi-step transaction. Prefer immutable values or isolated ownership where possible, and keep blocking work outside a critical section when correctness permits.", "examples": ["Lost update: A and B both read count=0, then both write 1. A mutex around increment makes the final count 2.", "Connection pool: a semaphore with three permits allows at most three simultaneous borrowers."], "nodes": ["A reads 0", "B reads 0", "A writes 1", "B writes 1"], "steps": ["Thread A reads the shared counter before changing it.", "Thread B reads the same old value before A writes.", "A computes 0+1 and writes 1.", "B also writes 1. Two increments produced 1: protect the whole read-modify-write."], "pitfall": "A mutex in one process cannot protect a database invariant against other independent service processes.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Race%20conditions%2C%20mutexes%2C%20semaphores%20%26%20deadlock%20explained%20computer%20science", "takeaway": "A mutex in one process cannot protect a database invariant against other independent service processes."}, {"id": "virtual-memory-paging-file-systems", "module": "foundations", "title": "Virtual memory, paging & file systems", "level": "Foundation", "concept": "Virtual memory gives each process a private address view. Page tables map virtual pages to physical frames; a TLB caches recent translations. A page fault transfers control to the kernel when a translation or access needs handling. A fault does not always mean a disk read: zero-fill, copy-on-write, and already cached file pages are common cases.", "deep": "A file system maps names and metadata to stored data blocks, with directories, permissions, and allocation structures. Journaling helps recover metadata consistency after crashes but is not a backup. Buffered I/O passes through the page cache, so a completed write call may not yet mean durable storage. Working sets larger than RAM can cause severe paging pressure and latency.", "examples": ["Copy-on-write: a child initially shares a parent’s pages; writing a shared page creates a private copy.", "File read: the kernel serves a recently read block from the page cache without another storage request."], "nodes": ["Virtual address", "TLB lookup", "Page table", "Physical frame"], "steps": ["A process loads a virtual address containing a page number and offset.", "Check the TLB for a cached translation.", "On a TLB miss, walk page tables; a valid mapping need not cause a page fault.", "Combine the physical frame with the offset and perform the memory access."], "pitfall": "Virtual memory is not unlimited RAM. Durability requires the right synchronization and storage guarantees.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Virtual%20memory%2C%20paging%20%26%20file%20systems%20explained%20computer%20science", "takeaway": "Virtual memory is not unlimited RAM. Durability requires the right synchronization and storage guarantees."}, {"id": "blocking-async-i-o-select-poll-epoll", "module": "foundations", "title": "Blocking, async I/O & select/poll/epoll", "level": "Advanced", "concept": "Blocking I/O waits inside the call until progress is available. Non-blocking I/O returns immediately if it would have to wait, often with EAGAIN. Asynchronous I/O separates submission from completion. Readiness notification, such as epoll on Linux, tells you an operation is likely to progress; it does not itself read the data or promise an entire application message is available.", "deep": "select scans descriptor sets and has interface limits; poll uses descriptor arrays; epoll maintains registered interests and returns ready events. An event loop waits for readiness, runs callbacks, and tries non-blocking operations. With edge-triggered notification, drain reads until EAGAIN or you may miss progress. Slow CPU work inside a callback prevents the loop from serving other ready sockets.", "examples": ["A blocking read holds a worker while a client is silent; non-blocking read reports no data and lets other work run.", "A chat server registers thousands of sockets with epoll and processes only sockets reported ready."], "nodes": ["Register socket", "Wait in epoll", "Ready event", "Read until EAGAIN"], "steps": ["Add a non-blocking socket to the interest set.", "The loop sleeps efficiently rather than repeatedly checking every socket.", "The kernel reports readable readiness when data or a terminal condition is present.", "Read available bytes and handle EOF/errors; for edge-triggering, drain until EAGAIN."], "pitfall": "Readiness is not completion. A readable event may indicate EOF, and one read may return a partial message.", "minutes": 11, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Blocking%2C%20async%20I/O%20%26%20select/poll/epoll%20explained%20computer%20science", "takeaway": "Readiness is not completion. A readable event may indicate EOF, and one read may return a partial message."}, {"id": "oop-solid-composition", "module": "foundations", "title": "OOP, SOLID & composition", "level": "Foundation", "concept": "Encapsulation keeps valid state behind a clear interface. Abstraction exposes useful behavior while hiding details. Inheritance expresses an is-a relationship; polymorphism lets different implementations satisfy one contract. Composition builds behavior from collaborators and is often easier to change than deep inheritance. The goal is not more classes, but boundaries that make rules explicit and changes local.", "deep": "SOLID means single responsibility, open/closed, Liskov substitution, interface segregation, and dependency inversion. A subtype must preserve its parent’s behavioral promises, not just compile with the same methods. Depend on small abstractions where implementations vary. Avoid creating an interface for every trivial class: introduce boundaries that support meaningful substitution, testing, or ownership.", "examples": ["Payment service depends on a PaymentGateway contract; a test gateway and a real gateway implement the same behavior.", "Composition: a Report contains a Formatter instead of inheriting from PDFReport and HTMLReport hierarchies."], "nodes": ["Checkout", "Gateway interface", "Card gateway", "Payment result"], "steps": ["Checkout asks for payment without knowing the network library.", "The interface defines success, failure, and idempotency expectations.", "A card gateway implements the contract and handles provider-specific details.", "Return a domain result so checkout does not depend on transport exceptions."], "pitfall": "Liskov substitution is about behavior and invariants, not only matching method signatures.", "minutes": 10, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=OOP%2C%20SOLID%20%26%20composition%20explained%20computer%20science", "takeaway": "Liskov substitution is about behavior and invariants, not only matching method signatures."}, {"id": "seven-practical-design-patterns", "module": "foundations", "title": "Seven practical design patterns", "level": "Foundation", "concept": "Factory centralizes selecting an implementation; Builder assembles a complex object in valid stages. Strategy swaps an algorithm behind an interface. Observer notifies subscribers when something happens. Decorator wraps the same interface to add behavior; Adapter translates an incompatible interface. Singleton limits construction to one instance in a defined scope, but often hides dependencies and complicates tests.", "deep": "Patterns name recurring trade-offs, not mandatory scaffolding. A function or constructor is often enough for a factory or strategy. Observer callbacks need explicit lifecycle and failure handling. Decorator order matters: retry around logging differs from logging around retry. A singleton in each service process does not become a globally unique distributed object.", "examples": ["Decorator: wrap a repository with caching, then tracing, while keeping the repository interface.", "Adapter: turn an old SMS provider’s sendText(number,msg) into a NotificationSender.send(notification) contract."], "nodes": ["Caller", "Tracing decorator", "Cache decorator", "Repository"], "steps": ["The caller invokes the repository contract.", "Tracing starts a span and forwards the call.", "Caching checks for a stored result before forwarding a miss.", "The underlying repository loads data; wrappers observe and transform the returning result."], "pitfall": "Use a pattern to solve an actual variation or boundary problem; unnecessary layers make simple code harder to follow.", "minutes": 10, "references": [["OpenDSA textbook", "https://opendsa-server.cs.vt.edu/ODSA/Books/Everything/html/"], ["Linux man pages", "https://man7.org/linux/man-pages/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Seven%20practical%20design%20patterns%20explained%20computer%20science", "takeaway": "Use a pattern to solve an actual variation or boundary problem; unnecessary layers make simple code harder to follow."}, {"id": "http-the-request-response-journey", "module": "networking", "title": "HTTP: the request–response journey", "level": "Foundation", "concept": "HTTP is an application-layer protocol for exchanging representations of resources. A client sends a method, a target, headers, and sometimes a body. The server interprets the request and returns a status, headers, and an optional body. A request for /products/42 is separate from the network connection carrying it; one connection can carry many requests. HTTP statelessness means each request carries enough context to be understood independently.", "deep": "GET retrieves a representation, POST asks a resource to process input, PUT replaces a target representation, and DELETE removes it. Status families distinguish success (2xx), redirection (3xx), client-side conditions (4xx), and server-side failures (5xx). Headers describe content type, caching, authorization, and more. HTTPS adds TLS protection. In the lab, change the method and response, then watch the request travel through client, network, server, and storage.", "examples": ["Open a product: GET /products/42 returns 200 with JSON containing the name and price.", "Create an order: POST /orders with a JSON body returns 201 and a Location header for the new order."], "nodes": ["Your browser", "Network", "API server", "Database"], "steps": ["The browser constructs GET /products/42 with Accept: application/json.", "Request bytes travel over an established connection. Latency is not server processing time.", "The server routes the method and path, validates input, and checks authorization.", "Storage returns product 42. The server sends 200 OK plus JSON back to the browser."], "pitfall": "HTTP 200 alone does not prove a business operation succeeded; define response semantics and handle failures explicitly.", "minutes": 12, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": ["WvSVSbGo0wI", "HTTP vs HTTPS explained", "ByteByteGo"], "searchVideo": "https://www.youtube.com/results?search_query=HTTP%3A%20the%20request%E2%80%93response%20journey%20explained%20computer%20science", "takeaway": "HTTP 200 alone does not prove a business operation succeeded; define response semantics and handle failures explicitly."}, {"id": "osi-tcp-ip-sockets-ports-nat", "module": "networking", "title": "OSI, TCP/IP, sockets, ports & NAT", "level": "Foundation", "concept": "Layering separates concerns. The OSI model describes seven conceptual layers; TCP/IP groups these into application, transport, internet, and link. Backend engineers most often reason about L7 application messages and L4 transport connections. IP addresses locate network interfaces; ports help the OS deliver traffic to the correct transport endpoint. A socket is the program’s interface to that communication.", "deep": "A TCP connection is identified by source/destination addresses and ports. A listening socket accepts new connections and creates connected sockets. NAT rewrites address and often port mappings between private and public networks, maintaining state for return traffic. A forward proxy acts for clients; a reverse proxy fronts servers. Neither a port number nor the OSI diagram provides authentication or encryption.", "examples": ["Your laptop 192.168.1.4:53000 connects to a server on port 443; NAT maps it to a public source port.", "An L4 balancer forwards a connection based on transport information; an L7 balancer can route /api by HTTP path."], "nodes": ["Private socket", "NAT mapping", "Public network", "Server :443"], "steps": ["The application opens a socket from a private address and ephemeral port.", "The router records a translation to its public address and port.", "Packets use public routing while preserving the destination server.", "Return packets match the NAT mapping and reach the originating socket."], "pitfall": "NAT is not a substitute for firewall rules or application authorization.", "minutes": 11, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=OSI%2C%20TCP/IP%2C%20sockets%2C%20ports%20%26%20NAT%20explained%20computer%20science", "takeaway": "NAT is not a substitute for firewall rules or application authorization."}, {"id": "tcp-udp-the-three-way-handshake", "module": "networking", "title": "TCP, UDP & the three-way handshake", "level": "Foundation", "concept": "TCP provides an ordered byte stream with loss recovery, duplicate suppression, and flow/congestion control. It does not preserve application message boundaries, so applications need framing such as lengths or delimiters. UDP sends independent datagrams without built-in reliable delivery or ordering. Applications can add reliability above UDP; QUIC is an important example.", "deep": "A TCP connection normally begins with SYN, SYN-ACK, and ACK to synchronize sequence numbers and confirm two-way reachability. Retransmission repairs loss but introduces delay. UDP’s smaller transport contract is useful when timeliness or custom transport behavior matters, such as media and games. It does not guarantee lower application latency; implementation, loss, and network policies still matter.", "examples": ["HTTP/1.1 can receive half a request in one read and the rest later because TCP is a byte stream.", "A live game may drop an old position datagram instead of waiting to retransmit it after a newer position arrives."], "nodes": ["Client SYN", "Server SYN-ACK", "Client ACK", "Established"], "steps": ["The client sends SYN with its initial sequence number.", "The server acknowledges that sequence and sends its own SYN.", "The client acknowledges the server sequence, completing the normal handshake.", "Both endpoints can exchange a reliable ordered byte stream."], "pitfall": "One TCP write does not equal one TCP read. Add framing above the stream.", "minutes": 10, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=TCP%2C%20UDP%20%26%20the%20three-way%20handshake%20explained%20computer%20science", "takeaway": "One TCP write does not equal one TCP read. Add framing above the stream."}, {"id": "flow-control-congestion-head-of-line-blocking", "module": "networking", "title": "Flow control, congestion & head-of-line blocking", "level": "Intermediate", "concept": "Flow control protects the receiver: TCP advertises a receive window representing buffering capacity. Congestion control protects the network: the sender estimates a safe amount of in-flight data using a congestion window. The usable sending window is constrained by both. Packet loss and delay influence congestion behavior; a slow receiver and a congested path are different bottlenecks.", "deep": "Head-of-line blocking happens when later work waits behind earlier incomplete work. HTTP/1.1 request ordering can cause application-level blocking. HTTP/2 multiplexes streams, but lost TCP bytes can still stall delivery to all streams on that connection. QUIC delivers independent streams separately, reducing this cross-stream transport blocking, while still applying shared congestion control.", "examples": ["A phone with a full receive buffer shrinks its advertised window even when the network has spare capacity.", "Two HTTP/2 images share a TCP connection; a missing earlier TCP segment temporarily blocks later stream data."], "nodes": ["Send segments 1–3", "Segment 2 lost", "3 arrives buffered", "2 retransmitted"], "steps": ["The sender transmits within both flow and congestion limits.", "The network drops segment 2.", "TCP buffers later bytes but cannot deliver a gap-filled ordered stream yet.", "Retransmitted segment 2 fills the gap; waiting data can now reach applications."], "pitfall": "HTTP/2 multiplexing does not remove TCP-level head-of-line blocking.", "minutes": 10, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Flow%20control%2C%20congestion%20%26%20head-of-line%20blocking%20explained%20computer%20science", "takeaway": "HTTP/2 multiplexing does not remove TCP-level head-of-line blocking."}, {"id": "http-1-1-http-2-http-3-hpack-quic", "module": "networking", "title": "HTTP/1.1, HTTP/2, HTTP/3, HPACK & QUIC", "level": "Intermediate", "concept": "HTTP versions preserve application semantics while changing transport efficiency. HTTP/1.1 supports persistent connections but typically uses multiple connections for parallel requests. HTTP/2 frames multiple streams over one TCP connection and compresses headers with HPACK. HTTP/3 maps HTTP onto QUIC, which runs over UDP, integrates TLS 1.3, and supports independent stream delivery.", "deep": "HPACK uses indexed fields and literal encodings to avoid repeatedly sending verbose headers; shared compression state requires careful decoding and security design. HTTP/3 uses QPACK instead, adapted to avoid unnecessary cross-stream dependencies. QUIC supports connection IDs and migration, helping a connection survive some network changes. Reusing connections avoids repeated setup, but congestion, server limits, and network support still affect real performance.", "examples": ["HTTP/2: one connection carries HTML, CSS, and an image as separately identified streams.", "HTTP/3: loss on one stream need not stop delivery on another stream whose required bytes arrived."], "nodes": ["One connection", "Stream 1 HTML", "Stream 3 CSS", "Interleaved frames"], "steps": ["Negotiate HTTP/2 over a TLS connection.", "Create a stream for the HTML response.", "Create another stream for CSS instead of opening another TCP connection.", "Frames interleave and are reassembled by stream ID. TCP loss can still stall both."], "pitfall": "HTTP/3 uses QPACK, not HPACK. UDP under QUIC does not mean QUIC is unreliable.", "minutes": 11, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=HTTP/1.1%2C%20HTTP/2%2C%20HTTP/3%2C%20HPACK%20%26%20QUIC%20explained%20computer%20science", "takeaway": "HTTP/3 uses QPACK, not HPACK. UDP under QUIC does not mean QUIC is unreliable."}, {"id": "dns-resolvers-records-anycast", "module": "networking", "title": "DNS, resolvers, records & Anycast", "level": "Foundation", "concept": "DNS translates names into records. A records contain IPv4 addresses, AAAA records IPv6 addresses, and CNAME records aliases to other names. A recursive resolver answers clients, using its cache or querying the DNS hierarchy. Root servers refer it toward a TLD such as .com, and a TLD refers it toward the domain’s authoritative servers. The authoritative answer has a TTL controlling cache lifetime.", "deep": "The browser, operating system, and resolver may each cache results. A CNAME can require additional lookups, and negative answers can be cached too. Anycast advertises one IP from multiple network locations so routing can reach a nearby or otherwise preferred instance. It helps distribute DNS service but does not mean the DNS answer always points to the geographically closest application server.", "examples": ["api.example.com is a CNAME to edge.example.net, whose A record resolves to an IPv4 address.", "A cached answer with 40 seconds of TTL remaining can avoid contacting authoritative servers on the next lookup."], "nodes": ["Browser", "Recursive resolver", "Root → TLD", "Authoritative DNS"], "steps": ["The browser asks its configured resolver for api.example.com.", "A cache miss requires recursive resolution; a cache hit can answer immediately.", "The root and then TLD provide referrals rather than the final application IP.", "The authoritative server returns the record; the resolver caches it for its TTL."], "pitfall": "DNS changes do not invalidate all existing caches instantly; plan migrations around TTLs and connection reuse.", "minutes": 11, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=DNS%2C%20resolvers%2C%20records%20%26%20Anycast%20explained%20computer%20science", "takeaway": "DNS changes do not invalidate all existing caches instantly; plan migrations around TTLs and connection reuse."}, {"id": "https-tls-certificate-trust", "module": "networking", "title": "HTTPS, TLS & certificate trust", "level": "Foundation", "concept": "HTTPS is HTTP protected by TLS. TLS authenticates the server, establishes traffic keys, and encrypts and integrity-protects application data. Public-key mechanisms support authentication and key agreement; fast symmetric encryption protects the ongoing traffic. A certificate binds a public key to identities such as domain names and is signed within a chain the client can validate against trusted roots.", "deep": "In a simplified TLS 1.3 handshake, ClientHello proposes parameters and a key share; the server replies with its share and authenticated handshake messages. The client validates the certificate chain, hostname, validity, and handshake proof before trusting application data. Session resumption can reduce setup cost. TLS does not protect data after an authorized endpoint decrypts it, and certificates do not prove a business is honest.", "examples": ["A browser rejects a valid certificate for other.example when connecting to shop.example because the hostname does not match.", "An eavesdropper sees encrypted HTTPS payload bytes rather than the submitted password, though some metadata remains visible."], "nodes": ["ClientHello", "ServerHello", "Certificate validation", "Encrypted HTTP"], "steps": ["The client proposes TLS parameters and a key share.", "The server supplies its share; both sides derive secret key material.", "The client checks the certificate identity, trust chain, and handshake authentication.", "Authenticated encryption protects request and response content using derived traffic keys."], "pitfall": "TLS is more than encrypting with a certificate’s public key. Modern handshakes use key agreement and forward secrecy.", "minutes": 11, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": ["j9QmMEWmcfo", "SSL, TLS, HTTPS explained", "ByteByteGo"], "searchVideo": "https://www.youtube.com/results?search_query=HTTPS%2C%20TLS%20%26%20certificate%20trust%20explained%20computer%20science", "takeaway": "TLS is more than encrypting with a certificate’s public key. Modern handshakes use key agreement and forward secrecy."}, {"id": "cors-cookies-headers-csp-hsts", "module": "networking", "title": "CORS, cookies, headers, CSP & HSTS", "level": "Foundation", "concept": "Cookies are browser-managed values attached to requests according to domain, path, and security rules. HttpOnly restricts JavaScript access; Secure requires secure transport; SameSite limits some cross-site sending. CORS lets a server opt into cross-origin JavaScript access through response headers. A preflight OPTIONS request checks permission for certain methods and headers before the browser sends the actual request.", "deep": "CORS is a browser read-access policy, not general API authentication or reliable CSRF prevention. Content Security Policy restricts permitted sources and actions to reduce the impact of script injection. HSTS instructs browsers to use HTTPS for a host for a period; it does not encrypt traffic by itself. Use narrow policies, understand credentialed requests, and add server-side authorization regardless of browser policy.", "examples": ["A frontend at app.example requests api.example; the API must explicitly allow that origin for browser JavaScript access.", "A CSP that avoids inline script and permits only trusted scripts can block many injected script executions."], "nodes": ["Frontend origin", "OPTIONS preflight", "API permission", "Actual request"], "steps": ["JavaScript attempts a cross-origin request with an application/json body.", "The browser sends OPTIONS describing the intended method and headers.", "The API responds with narrowly scoped allowed origin, methods, and headers.", "If permission matches, the browser sends the actual request; the API still authenticates it."], "pitfall": "HttpOnly reduces token theft through JavaScript but XSS can still perform actions as the user.", "minutes": 11, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=CORS%2C%20cookies%2C%20headers%2C%20CSP%20%26%20HSTS%20explained%20computer%20science", "takeaway": "HttpOnly reduces token theft through JavaScript but XSS can still perform actions as the user."}, {"id": "what-happens-when-you-type-a-url", "module": "networking", "title": "What happens when you type a URL?", "level": "Foundation", "concept": "A navigation begins by parsing the URL, applying applicable security policies, and checking caches. DNS resolves the hostname if necessary. The browser establishes or reuses transport: often TCP plus TLS for HTTPS, or QUIC for HTTP/3. It sends HTTP, receives a response, follows permitted redirects, parses HTML, and fetches linked resources before layout and rendering.", "deep": "The critical path can include DNS, connection setup, server processing, and payload transfer. A new TCP plus TLS connection typically adds round trips, while reuse avoids repeating much of that work. Compression reduces bytes but costs CPU. Cache validation may return 304 with no full body. A waterfall and timing breakdown reveal which stage dominates rather than assuming the backend is always slow.", "examples": ["First visit: DNS and a new connection add setup delay before the first request can complete.", "Second visit: a cached DNS answer, reused connection, and fresh CSS cache remove several earlier steps."], "nodes": ["Parse URL", "Resolve & connect", "HTTP exchange", "Parse & render"], "steps": ["Extract scheme, host, port, and path; apply relevant HTTPS policy.", "Resolve the host if needed, then establish or reuse a secure transport.", "Send the request and receive status, headers, and body.", "Parse HTML, request dependencies, execute scripts as scheduled, and render the page."], "pitfall": "A simple navigation diagram is a model: service workers, proxies, redirects, caches, and HTTP version change the actual path.", "minutes": 11, "references": [["MDN HTTP guide", "https://developer.mozilla.org/en-US/docs/Web/HTTP"], ["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=What%20happens%20when%20you%20type%20a%20URL%3F%20explained%20computer%20science", "takeaway": "A simple navigation diagram is a model: service workers, proxies, redirects, caches, and HTTP version change the actual path."}, {"id": "memory-garbage-collection-python-allocations", "module": "runtimes", "title": "Memory, garbage collection & Python allocations", "level": "Foundation", "concept": "Runtime memory management controls object allocation and reclamation. A stack holds call-local execution state; a heap holds objects whose lifetimes may outlive a call. Tracing garbage collectors find unreachable objects from roots; CPython primarily uses reference counting with a cyclic collector. A reachable object can still be an accidental memory leak if an unbounded cache keeps it alive.", "deep": "Garbage collection is not free: throughput, pause duration, allocation rate, and retained heap size interact. Python generators produce values incrementally and can avoid loading a whole dataset, but downstream consumers may still materialize it. Slices, serialization, and conversion can duplicate large arrays. Profile retained objects and peak memory rather than trusting object count alone.", "examples": ["Instead of reading a 2 GB CSV into a list, stream rows through a generator and process bounded batches.", "A global dictionary holding every request body stays reachable and grows forever; the GC cannot infer that you no longer need it."], "nodes": ["Allocate object", "Keep reference", "Drop reference", "Reclaim memory"], "steps": ["Create an object and store its address in a variable.", "The runtime considers it live while reachable from roots.", "Remove its last useful reference; a cycle may require cyclic collection.", "The runtime reclaims the object according to its collector, though RSS need not immediately fall."], "pitfall": "Garbage collection does not replace bounded caches, closing resources, or measuring peak allocations.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Memory%2C%20garbage%20collection%20%26%20Python%20allocations%20explained%20computer%20science", "takeaway": "Garbage collection does not replace bounded caches, closing resources, or measuring peak allocations."}, {"id": "routing-middleware-di-validation", "module": "runtimes", "title": "Routing, middleware, DI & validation", "level": "Foundation", "concept": "Routing maps a method and path to a handler. Middleware wraps request processing for concerns such as authentication, timing, and correlation IDs. Dependency injection supplies collaborators rather than constructing them secretly inside business logic. A DTO defines the data crossing a boundary, while validation rejects malformed inputs before they reach domain operations.", "deep": "Separate transport errors from domain errors and unexpected faults. Return safe, consistent error bodies with a request ID; log context rather than passwords or full tokens. Middleware order affects behavior: timing outside error handling sees a different boundary than timing inside it. Validate types, lengths, and business permissions independently. Build tools and package managers should produce reproducible, pinned dependency graphs.", "examples": ["POST /orders validates quantity as a positive integer before the service reserves inventory.", "A handler receives an injected repository; tests provide an in-memory implementation without connecting to production."], "nodes": ["Request", "Middleware", "Validated DTO", "Service"], "steps": ["Route POST /orders to the order handler.", "Attach a request ID and verify the caller’s authentication.", "Parse the body into a DTO and reject invalid fields with a clear error.", "Inject dependencies, enforce domain rules, and serialize a safe response."], "pitfall": "Valid JSON is not necessarily a valid business operation; authorization and invariants still need checking.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Routing%2C%20middleware%2C%20DI%20%26%20validation%20explained%20computer%20science", "takeaway": "Valid JSON is not necessarily a valid business operation; authorization and invariants still need checking."}, {"id": "java-threads-pools-concurrent-primitives", "module": "runtimes", "title": "Java threads, pools & concurrent primitives", "level": "Foundation", "concept": "Java platform threads can execute in parallel across cores. ExecutorService separates submitting tasks from managing threads. A bounded thread pool amortizes creation and limits active work. synchronized provides mutual exclusion and visibility; volatile provides visibility and ordering for a variable but does not make a compound increment atomic. Atomic classes implement suitable indivisible updates.", "deep": "ConcurrentHashMap supports concurrent map operations, but separate get and put calls are not one atomic workflow; use appropriate compute or merge operations. CompletableFuture composes asynchronous results, yet a blocking stage can still consume its executor thread. Explicitly choose executors, bound queues, handle cancellation, and propagate failures. More threads can overload the database rather than improve the application.", "examples": ["AtomicInteger.incrementAndGet() prevents lost increments; volatile int plus count++ does not.", "Run two independent HTTP calls in a chosen executor and combine their futures, with a deadline and failure handling."], "nodes": ["Submit tasks", "Bounded queue", "Pool workers", "Future result"], "steps": ["Three tasks are submitted through ExecutorService.", "Tasks wait if workers are occupied, subject to the configured queue policy.", "Workers execute tasks and release capacity when complete.", "Callers observe results or exceptions through futures rather than silently losing failures."], "pitfall": "CompletableFuture does not automatically make blocking code non-blocking, and unbounded submission can exhaust memory.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Java%20threads%2C%20pools%20%26%20concurrent%20primitives%20explained%20computer%20science", "takeaway": "CompletableFuture does not automatically make blocking code non-blocking, and unbounded submission can exhaust memory."}, {"id": "python-gil-threads-processes-asyncio", "module": "runtimes", "title": "Python GIL, threads, processes & asyncio", "level": "Foundation", "concept": "In a conventional GIL-enabled CPython build, one thread at a time executes Python bytecode. Threads can still overlap blocking I/O because the interpreter releases the GIL around many waits; native extensions may release it during computation too. Processes use separate interpreters and memory, allowing CPU parallelism with communication and startup costs. asyncio cooperatively interleaves coroutines on an event loop.", "deep": "Choose from the workload: network waiting often suits async or threads; Python CPU work often suits processes. An await yields only when the awaited operation suspends; it does not magically offload synchronous computation. Free-threaded CPython is an optional, supported build option from Python 3.14, rather than the default build. Extension compatibility and application synchronization still matter; removing the GIL does not remove races.", "examples": ["Threading: fetch ten independent slow pages while network waits overlap.", "Multiprocessing: split CPU-heavy image transforms among worker processes, accounting for transfer and model-copy costs."], "nodes": ["Coroutine A", "Await socket", "Run B", "Resume A"], "steps": ["A begins a non-blocking request.", "A suspends while waiting for readiness, returning control to the event loop.", "The loop advances B on the same thread rather than waiting idly.", "When A’s I/O completes, the loop schedules its continuation."], "pitfall": "Free-threaded support is version/build dependent. Do not assume the GIL exists, or that its absence makes shared mutations safe.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Python%20GIL%2C%20threads%2C%20processes%20%26%20asyncio%20explained%20computer%20science", "takeaway": "Free-threaded support is version/build dependent. Do not assume the GIL exists, or that its absence makes shared mutations safe."}, {"id": "virtual-threads-structured-concurrency", "module": "runtimes", "title": "Virtual threads & structured concurrency", "level": "Intermediate", "concept": "Java virtual threads are lightweight Java threads scheduled onto carrier platform threads. Supported blocking I/O can unmount a virtual thread, allowing its carrier to serve other runnable work. They make a thread-per-task style practical for many waiting tasks, but do not make CPU work faster or increase downstream capacity. Limit access to scarce resources separately with pools or semaphores.", "deep": "Virtual threads became final in Java 21. Pinning advice is version-sensitive: JDK 24’s JEP 491 removes the ordinary synchronized-related pinning limitation, while native-related cases can remain. Structured concurrency groups child tasks within an owning scope so lifetime, cancellation, and error propagation are easier to reason about; check the chosen JDK’s API and preview status before relying on it.", "examples": ["Ten thousand virtual threads wait for remote responses while a smaller carrier pool runs the ready continuations.", "A product-page scope starts price and inventory tasks; if the parent deadline expires, it cancels both children."], "nodes": ["Virtual task", "Carrier thread", "Blocking I/O", "Carrier reused"], "steps": ["A virtual thread runs on a carrier.", "It executes normal Java code until a supported blocking operation.", "The waiting virtual thread unmounts, retaining its logical stack.", "The carrier runs another task; the waiting task resumes when ready."], "pitfall": "Virtual threads are not a reason to allow unlimited database connections or ignore JDK-version-specific pinning behavior.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Virtual%20threads%20%26%20structured%20concurrency%20explained%20computer%20science", "takeaway": "Virtual threads are not a reason to allow unlimited database connections or ignore JDK-version-specific pinning behavior."}, {"id": "tomcat-connectors-thread-pool-sizing", "module": "runtimes", "title": "Tomcat connectors & thread pool sizing", "level": "Intermediate", "concept": "Tomcat’s HTTP connector accepts connections, detects ready input, and dispatches servlet processing. With platform threads, a worker generally remains occupied while servlet code blocks. maxThreads bounds processing workers; maxConnections bounds accepted connections; acceptCount relates to the pending connection backlog once accepting capacity is reached. Exact settings interact with connector, executor, and virtual-thread configuration.", "deep": "CPU-bound pool sizing near core count is a starting point, not a law. For waiting work, cores × (1 + wait/compute) is a rough capacity heuristic. Little’s Law L=λW relates average in-flight work, arrival throughput, and response time in a stable system. Bound queues and set downstream timeouts, because slow database calls can hold every worker and turn a small delay into thread starvation.", "examples": ["At 100 requests/s and mean latency 0.2 s, average in-flight requests are about 20.", "If all 20 workers wait on a failed API, new requests queue even when CPU utilization is low."], "nodes": ["Connector", "Work queue", "Servlet worker", "Downstream call"], "steps": ["Accept a connection subject to configured connection limits.", "Ready requests seek processing capacity; a growing queue adds latency.", "A worker runs servlet code and holds its slot during blocking calls.", "A timeout frees the worker if the dependency fails to respond."], "pitfall": "A larger queue hides overload temporarily while increasing tail latency; pool sizing must respect downstream limits.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Tomcat%20connectors%20%26%20thread%20pool%20sizing%20explained%20computer%20science", "takeaway": "A larger queue hides overload temporarily while increasing tail latency; pool sizing must respect downstream limits."}, {"id": "fastapi-asgi-uvicorn-blocking-calls", "module": "runtimes", "title": "FastAPI, ASGI, Uvicorn & blocking calls", "level": "Foundation", "concept": "ASGI is an async-capable server/application interface supporting HTTP, WebSockets, and lifecycle events. WSGI is a synchronous HTTP application interface. Uvicorn runs an ASGI application and its event loop. FastAPI executes async def handlers on the loop and normal def handlers in a thread pool. A synchronous helper called directly inside async def is still synchronous.", "deep": "Use async drivers for awaited network I/O. Offload unavoidable blocking calls appropriately; move heavy computation into processes or a real worker service. Multiple worker processes use more cores but also duplicate process-local state, pools, and loaded models. Gunicorn can manage ASGI workers with a compatible worker implementation. Framework background tasks run in the application’s lifecycle and are not a durable replacement for Celery or another external task queue.", "examples": ["Good: await an async database client while other requests progress on the event loop.", "Bad: requests.get() or time.sleep() inside async def stalls that worker’s event loop until it returns."], "nodes": ["ASGI request", "async handler", "Await database", "Resume response"], "steps": ["Uvicorn delivers the request to FastAPI through ASGI.", "The async handler starts work on the event loop.", "An actual async database wait yields control so other requests progress.", "The driver signals completion and the handler builds its response."], "pitfall": "Changing def to async def does not convert a synchronous database or HTTP library into non-blocking code.", "minutes": 11, "references": [["Python free-threading guide", "https://docs.python.org/3/howto/free-threading-python.html"], ["Virtual threads • JEP 491", "https://openjdk.org/jeps/491"], ["FastAPI async guide", "https://fastapi.tiangolo.com/async/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=FastAPI%2C%20ASGI%2C%20Uvicorn%20%26%20blocking%20calls%20explained%20computer%20science", "takeaway": "Changing def to async def does not convert a synchronous database or HTTP library into non-blocking code."}, {"id": "rest-methods-status-codes-idempotency", "module": "apis", "title": "REST, methods, status codes & idempotency", "level": "Foundation", "concept": "REST organizes an interface around resources and representations, with stateless requests and standard HTTP semantics. Safe methods such as GET should not request state changes. Idempotency means repeating a request has the same intended effect as making it once; it does not require identical response bodies or forbid logging. PUT and DELETE are defined as idempotent, while POST generally is not.", "deep": "For operations such as payment creation, accept an idempotency key, bind it to the caller and request payload, and atomically store the result with the effect. A retry must reuse the same key. Use meaningful status codes, input validation, filtering, and sorting contracts. OpenAPI documents the machine-readable contract; versioning should manage compatibility rather than creating a new version for every internal refactor.", "examples": ["DELETE /cart/items/7 twice leaves the item absent even if the second response is 404.", "POST /payments with key K returns the saved result on retry instead of charging the card twice."], "nodes": ["POST + key K", "Lookup K", "Atomic creation", "Replay result"], "steps": ["The client submits an operation and a stable idempotency key.", "Check whether that caller and key already have a matching operation.", "For a new key, commit the effect and recorded result atomically.", "A retry with the same payload returns the stored result; a conflicting payload is rejected."], "pitfall": "A lookup followed by an unprotected insert can race; enforce uniqueness and transactional correctness.", "minutes": 11, "references": [["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"], ["MDN server-sent events", "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=REST%2C%20methods%2C%20status%20codes%20%26%20idempotency%20explained%20computer%20science", "takeaway": "A lookup followed by an unprotected insert can race; enforce uniqueness and transactional correctness."}, {"id": "offset-cursor-pagination", "module": "apis", "title": "Offset & cursor pagination", "level": "Foundation", "concept": "Offset pagination skips a count of ordered rows then returns a limit. It is convenient for page numbers, but deep offsets can be expensive and concurrent inserts can shift page boundaries. Cursor pagination resumes after a known ordered key and often scales better for feeds. The order must be deterministic, with a unique tie-breaker.", "deep": "For ORDER BY created_at DESC, id DESC, the next-page predicate compares both values from the last item. A cursor can encode those values plus filters and a version; signing can detect tampering. Cursors do not automatically provide a stable snapshot across changing data. Document consistency expectations, maximum page size, and whether total counts are approximate or expensive.", "examples": ["Offset: LIMIT 20 OFFSET 100 returns page six, but may still scan or skip the earlier rows.", "Cursor: after (10:00,42), request older rows using created_at and id so equal timestamps do not cause omissions."], "nodes": ["Ordered rows", "Page 1 ends at 42", "Encode cursor", "Seek next page"], "steps": ["Sort rows by timestamp and unique ID.", "Return the first bounded batch and retain the final key.", "Encode the final timestamp and ID rather than a mutable row position.", "Use an indexed comparison to seek the next ordered batch."], "pitfall": "A cursor based only on a non-unique timestamp can skip or duplicate rows with identical timestamps.", "minutes": 11, "references": [["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"], ["MDN server-sent events", "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Offset%20%26%20cursor%20pagination%20explained%20computer%20science", "takeaway": "A cursor based only on a non-unique timestamp can skip or duplicate rows with identical timestamps."}, {"id": "graphql-the-n-1-problem", "module": "apis", "title": "GraphQL & the N+1 problem", "level": "Intermediate", "concept": "GraphQL exposes a typed schema and lets clients select fields. Queries read data, mutations request changes, and subscriptions deliver ongoing results through a transport integration. Field selection can reduce over-fetching and repeated client requests, but a single flexible query may still generate excessive database work or an enormous response.", "deep": "N+1 occurs when resolving a list triggers one child query per item. Request-scoped batching and caching, such as a data loader, collect keys and fetch them together. Enforce authorization at the correct field and object boundaries, plus depth, cost, and pagination limits. GraphQL is an interface style, not a storage engine or an automatic solution for caching and performance.", "examples": ["A query asks for users { id name } without downloading each user’s unused biography.", "Ten orders need ten owners: batch unique owner IDs into one database query rather than issuing ten separate lookups."], "nodes": ["GraphQL query", "Resolve orders", "Batch owner IDs", "Attach owners"], "steps": ["Parse and validate the query against the schema.", "Load a bounded page of orders.", "Collect owner references across the result and fetch them in one batch.", "Map owners back to orders while enforcing per-object permissions."], "pitfall": "Fewer HTTP requests can still mean more backend work; measure query execution cost and database calls.", "minutes": 10, "references": [["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"], ["MDN server-sent events", "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=GraphQL%20%26%20the%20N%2B1%20problem%20explained%20computer%20science", "takeaway": "Fewer HTTP requests can still mean more backend work; measure query execution cost and database calls."}, {"id": "grpc-protobuf-streaming-types", "module": "apis", "title": "gRPC, Protobuf & streaming types", "level": "Intermediate", "concept": "gRPC defines services and typed messages, typically using Protocol Buffers and HTTP/2. Protobuf assigns numeric field tags and encodes compact messages; compatibility requires preserving tag meanings and avoiding reuse of removed tags. Generated stubs give callers a typed interface, but the call still crosses a network with partial failure and latency.", "deep": "Unary RPC has one request and one response. Server streaming returns multiple messages; client streaming submits multiple messages; bidirectional streaming allows both sides to send over time. Propagate deadlines and cancellation and respect flow control. Use gRPC where typed service contracts and streaming fit your clients; browser integration often requires an appropriate gateway or gRPC-Web rather than ordinary browser fetch.", "examples": ["Unary: GetUser(user_id) returns one User message.", "Server streaming: WatchJob(job_id) yields progress messages until the task completes or the deadline expires."], "nodes": ["Typed client", "Serialized message", "RPC service", "Stream results"], "steps": ["The generated client validates the message shape and attaches a deadline.", "Serialize fields using their stable Protobuf tags.", "The service processes the request within the caller’s remaining budget.", "Return one response or a stream according to the declared RPC type."], "pitfall": "A generated local-looking method is still a fallible remote call; never treat timeouts as proof that no effect occurred.", "minutes": 11, "references": [["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"], ["MDN server-sent events", "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=gRPC%2C%20Protobuf%20%26%20streaming%20types%20explained%20computer%20science", "takeaway": "A generated local-looking method is still a fallible remote call; never treat timeouts as proof that no effect occurred."}, {"id": "webhooks-secure-delivery", "module": "apis", "title": "Webhooks & secure delivery", "level": "Intermediate", "concept": "A webhook is an outbound HTTP notification from one service to another when an event occurs. The sender typically retries failures, so duplicates and out-of-order events must be expected. The receiver should authenticate the sender, validate the event, durably record or enqueue it, and return quickly. Business work can then happen asynchronously.", "deep": "Verify a provider’s signature using the exact raw payload bytes and a replay-resistant timestamp where supported. Deduplicate by a stable event ID and handle an event whose referenced resource is not yet visible. A 2xx response should mean accepted responsibility, not merely parsed JSON. Restrict outbound webhook destinations to prevent SSRF when users configure endpoints.", "examples": ["Payment provider sends payment.succeeded; record the event ID and enqueue order fulfillment before acknowledging.", "The sender retries the same event after a lost acknowledgement; the receiver recognizes its ID and avoids a second shipment."], "nodes": ["Event sender", "Signed POST", "Durable inbox", "Worker"], "steps": ["An event gets a stable ID and signature.", "The receiver checks signature and timestamp against the raw body.", "Insert the event once and accept it durably before replying 2xx.", "A worker performs the business action idempotently and records the result."], "pitfall": "Webhook authenticity and idempotency are separate requirements; both are needed.", "minutes": 10, "references": [["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"], ["MDN server-sent events", "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Webhooks%20%26%20secure%20delivery%20explained%20computer%20science", "takeaway": "Webhook authenticity and idempotency are separate requirements; both are needed."}, {"id": "websockets-sse-polling-job-progress", "module": "apis", "title": "WebSockets, SSE, polling & job progress", "level": "Foundation", "concept": "Short polling repeatedly requests current state; long polling holds a request until an update or timeout. Server-Sent Events sends server-to-client text events over HTTP, with browser reconnection support. WebSockets provide bidirectional messages after a connection establishment handshake. Choose from directionality, client support, proxy behavior, and operational cost rather than assuming every live interface needs WebSockets.", "deep": "For a long-running job, submit work, return a job ID and accepted status, then subscribe or poll separately. SSE event IDs and Last-Event-ID can support resume only if the server retains enough history or supplies a current snapshot. Add heartbeats, bounded buffers, reconnect backoff, and authorization on reconnect. Across instances, shared state or pub/sub can distribute progress; sticky sessions alone do not provide durable recovery.", "examples": ["LLM generation: POST /jobs returns job_id, then SSE streams stage and token updates to the browser.", "Chat: WebSockets carry both user messages and server pushes; a slow client gets bounded buffering or disconnect/resync."], "nodes": ["POST job", "202 + job_id", "SSE subscription", "Progress events"], "steps": ["The API validates and enqueues work rather than keeping the submit request blocked.", "Return an identifier the client can use for status and cancellation.", "The client opens an authenticated event stream for that job.", "Emit IDs and heartbeat comments; reconnect can resume from retained events or a snapshot."], "pitfall": "An open connection is not durable delivery. Resume, timeouts, and slow-client backpressure need explicit design.", "minutes": 11, "references": [["HTTP semantics • RFC 9110", "https://www.rfc-editor.org/rfc/rfc9110"], ["MDN server-sent events", "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=WebSockets%2C%20SSE%2C%20polling%20%26%20job%20progress%20explained%20computer%20science", "takeaway": "An open connection is not durable delivery. Resume, timeouts, and slow-client backpressure need explicit design."}, {"id": "sql-joins-ctes-windows-aggregation", "module": "databases", "title": "SQL joins, CTEs, windows & aggregation", "level": "Foundation", "concept": "JOIN combines related rows: INNER keeps matches, LEFT preserves every left-side row, and CROSS forms combinations. GROUP BY collapses rows into groups for aggregates. Window functions calculate across related rows while retaining individual rows. A CTE names a query expression for clarity; it is not automatically a performance optimization or a permanently stored result.", "deep": "Be precise about grain. Joining each order to multiple line items repeats order fields, so summing the order total afterward overcounts. COUNT(*) counts rows; COUNT(column) excludes nulls. Filtering a right-table column in WHERE can turn a LEFT JOIN into an effective inner join. Use deterministic ordering for ranking and understand how ties affect ROW_NUMBER, RANK, and DENSE_RANK.", "examples": ["LEFT JOIN customers to orders to show customers with zero orders; count the non-null order ID.", "SUM(amount) OVER (PARTITION BY account_id ORDER BY time,id) computes a running balance without collapsing transactions."], "nodes": ["Customers", "LEFT JOIN orders", "Group by customer", "Count order IDs"], "steps": ["Start with one row per customer.", "Attach matching orders, retaining a null order row for customers with none.", "Group the joined rows by the customer identity.", "COUNT(order_id) gives zero for an unmatched customer, whereas COUNT(*) would count its preserved row."], "pitfall": "Write down the intended row grain before joining or aggregating financial data.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=SQL%20joins%2C%20CTEs%2C%20windows%20%26%20aggregation%20explained%20computer%20science", "takeaway": "Write down the intended row grain before joining or aggregating financial data."}, {"id": "normalization-denormalization-data-models", "module": "databases", "title": "Normalization, denormalization & data models", "level": "Foundation", "concept": "Normalization organizes facts to reduce update anomalies. First normal form avoids repeating groups; second removes partial dependencies on part of a composite key; third removes inappropriate transitive dependencies. BCNF requires every determinant of a nontrivial dependency to be a superkey. These rules depend on actual business dependencies, not just how many tables exist.", "deep": "Denormalization deliberately duplicates or precomputes facts to serve a read pattern. It can speed reads but introduces synchronization, rebuild, and freshness costs. Choose a source of truth and define how derived data is updated and repaired. A normalized transactional model and a denormalized reporting view can coexist; the right design follows correctness and access requirements.", "examples": ["Store a customer address once in a customer table instead of copying the current address into every live profile record.", "An immutable invoice may deliberately store the billing address as a historical snapshot, even if the customer later moves."], "nodes": ["Duplicated facts", "Identify dependency", "Extract customer", "Reference by ID"], "steps": ["Two orders contain the same mutable customer contact details.", "Recognize customer_id→contact as one fact independent of the order.", "Store the current contact in a customer relation.", "Orders reference the customer; historical invoice snapshots remain explicitly separate facts."], "pitfall": "Duplication is not always an error: historical snapshots and derived read models require different consistency rules.", "minutes": 10, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Normalization%2C%20denormalization%20%26%20data%20models%20explained%20computer%20science", "takeaway": "Duplication is not always an error: historical snapshots and derived read models require different consistency rules."}, {"id": "acid-transactions-row-locking", "module": "databases", "title": "ACID, transactions & row locking", "level": "Foundation", "concept": "A transaction groups database changes into a unit. Atomicity gives all-or-nothing effects; consistency means preserving declared invariants; isolation controls concurrent interactions; durability defines survival after commit under the database’s storage guarantees. A transaction should protect the complete business operation, not just individual inserts. Constraints provide a final guard against invalid states.", "deep": "Pessimistic locking such as SELECT FOR UPDATE locks selected rows before changing them. Optimistic locking adds a version predicate and treats zero updated rows as a conflict. Keep transactions short, acquire locks in a consistent order, and retry appropriate transient failures from the beginning. External network calls inside a transaction extend lock duration and still are not rolled back by the database.", "examples": ["Transfer 50: debit wallet A and credit B in the same transaction so a failure cannot leave only the debit.", "UPDATE items SET stock=stock-1 WHERE id=7 AND stock>0 atomically prevents negative stock for that row."], "nodes": ["BEGIN", "Lock & validate", "Apply updates", "COMMIT / rollback"], "steps": ["Start one transaction around the invariant.", "Lock the relevant rows or use conditional updates, then validate available funds.", "Apply both debit and credit and record an audit reference.", "Commit all changes together; on a failure roll back the whole transaction."], "pitfall": "A database rollback cannot undo an email or external charge. Coordinate those effects with an outbox or explicit workflow.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=ACID%2C%20transactions%20%26%20row%20locking%20explained%20computer%20science", "takeaway": "A database rollback cannot undo an email or external charge. Coordinate those effects with an outbox or explicit workflow."}, {"id": "isolation-levels-mvcc-write-skew", "module": "databases", "title": "Isolation levels, MVCC & write skew", "level": "Intermediate", "concept": "Isolation determines what concurrent transactions can observe. Read Committed prevents dirty reads but separate statements may see different committed states. Repeatable Read promises more stable reads, though exact guarantees vary by engine. Serializable requires committed results equivalent to some serial execution, commonly aborting conflicting transactions. Dirty reads, non-repeatable reads, phantoms, lost updates, and write skew are distinct anomalies.", "deep": "PostgreSQL treats Read Uncommitted as Read Committed. Its MVCC Repeatable Read uses a transaction snapshot and prevents phantoms, but write skew remains possible. Serializable adds dependency tracking through SSI and can reject an unsafe execution, so retry the full transaction. MVCC lets readers view older versions rather than always blocking writers; old snapshots can delay cleanup and consume storage.", "examples": ["Read Committed: A reads balance 100; B commits 150; A’s next statement can read 150.", "Write skew: two on-call doctors each see the other working, then both independently go off call. Serializable can abort one transaction."], "nodes": ["A reads 100", "B writes 150", "B commits", "A reads again"], "steps": ["A starts a transaction and reads the current committed balance.", "B changes the balance in another transaction.", "B commits, making 150 visible to new statement snapshots.", "Read Committed can now show A 150; PostgreSQL Repeatable Read retains A’s earlier snapshot."], "pitfall": "Snapshot isolation is not serializability. Retry serialization failures from a fresh transaction.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Isolation%20levels%2C%20MVCC%20%26%20write%20skew%20explained%20computer%20science", "takeaway": "Snapshot isolation is not serializability. Retry serialization failures from a fresh transaction."}, {"id": "views-triggers-pl-pgsql", "module": "databases", "title": "Views, triggers & PL/pgSQL", "level": "Intermediate", "concept": "A view names a query and usually reads current underlying data when used. A materialized view stores a result that needs refreshing. A trigger runs database logic on specified events and can enforce auditing or maintain related state, but hidden work can make debugging difficult. Stored functions and procedures move selected operations close to the data.", "deep": "PostgreSQL’s procedural language is PL/pgSQL; Oracle’s is PL/SQL. Use database logic for atomic, data-centered rules while keeping ownership, permissions, deployment, and testing clear. A trigger that performs expensive row-by-row work can turn a bulk import into a bottleneck. Security-definer routines require carefully controlled search paths and permissions. Document side effects so callers know the actual transactional work.", "examples": ["A view exposes active customers without forcing every caller to repeat the same filter.", "An audit trigger appends actor, operation, and row reference within the same transaction as a ledger change."], "nodes": ["UPDATE statement", "Row trigger", "Audit insert", "Commit together"], "steps": ["The application updates one protected record.", "The configured trigger executes within that statement’s transaction.", "It appends an audit record with a stable reference and approved context.", "A successful commit persists both; a rollback removes both transactional effects."], "pitfall": "A materialized view is not automatically fresh, and hidden trigger work is still part of your latency budget.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Views%2C%20triggers%20%26%20PL/pgSQL%20explained%20computer%20science", "takeaway": "A materialized view is not automatically fresh, and hidden trigger work is still part of your latency budget."}, {"id": "b-trees-b-trees-lsm-storage", "module": "databases", "title": "B-trees, B+ trees & LSM storage", "level": "Intermediate", "concept": "An index maps searchable keys to data locations. B-tree families keep ordered pages with high fan-out, making trees shallow. In a B+ tree model, record references live in leaves and linked leaves support range scans. Real engines differ: PostgreSQL calls its implementation a B-tree; InnoDB uses clustered primary-key storage with secondary indexes pointing to the primary key.", "deep": "Updates maintain indexes too, causing page writes, splits, and write amplification. LSM designs buffer writes and merge sorted files through compaction, trading write efficiency against read, space, and compaction costs. Bloom filters can reduce unnecessary file reads. Neither structure is universally faster: point reads, ranges, write rate, memory, and durability requirements shape the choice.", "examples": ["Find IDs 100–110 by descending to the first matching leaf and scanning neighboring ordered entries.", "A write-heavy log store buffers inserts, flushes sorted files, then compacts them instead of updating one leaf per write."], "nodes": ["Root page", "Internal page", "Leaf page", "Range scan"], "steps": ["Compare the key against separators in the root.", "Choose a child page, eliminating most of the key space.", "Locate the first matching ordered leaf entry.", "Continue through leaves for a range rather than scanning the entire table."], "pitfall": "Do not assume every engine stores complete rows in B+ tree leaves; study its actual index and table layout.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=B-trees%2C%20B%2B%20trees%20%26%20LSM%20storage%20explained%20computer%20science", "takeaway": "Do not assume every engine stores complete rows in B+ tree leaves; study its actual index and table layout."}, {"id": "composite-covering-partial-indexes", "module": "databases", "title": "Composite, covering & partial indexes", "level": "Intermediate", "concept": "A composite index orders by multiple keys, such as (tenant_id, created_at, id). Leading equality conditions followed by a useful range or order are a common efficient pattern. A covering index contains the columns needed by a query, potentially avoiding table reads. A partial index stores only rows matching a predicate, reducing size for targeted access patterns.", "deep": "The leftmost-prefix rule is a useful design heuristic, not an absolute claim that later columns can never be used. Optimizers may exploit other strategies. PostgreSQL index-only scans also depend on visibility information. Low selectivity, mismatched expressions, casts, or a small table can make a sequential scan cheaper. Every extra index increases storage and write maintenance, so validate against representative queries.", "examples": ["WHERE tenant_id=7 ORDER BY created_at,id can benefit from a matching composite index.", "Index only unpaid invoices with WHERE paid_at IS NULL when operational queries focus on that subset."], "nodes": ["Query predicates", "Index prefix", "Matching range", "Covered output"], "steps": ["Filter by tenant_id=7 and request creation-time ordering.", "Seek to the contiguous region for tenant 7.", "Walk entries in time and ID order without sorting the whole table.", "Return indexed columns when engine visibility permits, otherwise fetch required table rows."], "pitfall": "An index existing does not mean the optimizer should use it; compare actual rows, I/O, and execution time.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Composite%2C%20covering%20%26%20partial%20indexes%20explained%20computer%20science", "takeaway": "An index existing does not mean the optimizer should use it; compare actual rows, I/O, and execution time."}, {"id": "explain-query-plans-connection-pools", "module": "databases", "title": "EXPLAIN, query plans & connection pools", "level": "Intermediate", "concept": "EXPLAIN shows the optimizer’s planned operators and estimates. EXPLAIN ANALYZE executes the statement and reports actual behavior, so it can modify data and incur real load. Sequential scans, index scans, nested loops, hash joins, and merge joins each fit different input sizes and ordering. Large estimate errors often point to stale statistics or correlations the estimator does not capture.", "deep": "Inspect actual rows, loop counts, buffers, sorts, and time rather than treating a sequential scan as inherently bad. pg_stat_statements and slow-query logs identify repeated workload costs. Connection pools cap expensive connections and queue work, but an oversized pool can overload the database. Use batching, bulk inserts, and keyset pagination for large datasets; avoid loading all records into application memory.", "examples": ["A nested loop with 100,000 outer rows and one inner query per row can dominate latency despite each inner query being fast.", "A pool of 20 connections limits database concurrency while a larger number of requests wait with explicit timeouts."], "nodes": ["Capture slow query", "Read estimates", "Measure actuals", "Change & compare"], "steps": ["Identify a real query from workload statistics rather than guessing.", "Inspect its planned row counts and access paths.", "Run safely with representative data and compare actual rows, loops, and buffers.", "Change one cause, such as an index or N+1 access pattern, then measure under comparable load."], "pitfall": "EXPLAIN ANALYZE executes the query, including writes. Use safe environments and understand side effects.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=EXPLAIN%2C%20query%20plans%20%26%20connection%20pools%20explained%20computer%20science", "takeaway": "EXPLAIN ANALYZE executes the query, including writes. Use safe environments and understand side effects."}, {"id": "nosql-key-value-document-column-graph", "module": "databases", "title": "NoSQL: key-value, document, column & graph", "level": "Foundation", "concept": "NoSQL names several data models rather than one set of guarantees. Key-value stores retrieve values by key; document stores group nested data; wide-column stores organize sparse, partitioned rows; graph databases emphasize connected entities and traversals. SQL versus NoSQL is a decision about access patterns, transactions, constraints, and operations, not simply structured versus unstructured data.", "deep": "MongoDB favors document modeling around frequently read aggregates; embedding and references have different update costs. DynamoDB requires deliberate partition/sort-key design and secondary-index planning. Cassandra favors query-driven denormalization with careful partition sizing. All can require schemas and migrations at the application level. Check each product’s actual consistency and transaction guarantees instead of assuming NoSQL means no transactions.", "examples": ["Key-value: session ID maps directly to a serialized session with an expiry.", "Graph: find friends-of-friends through relationship traversal rather than repeatedly joining an arbitrary-depth chain."], "nodes": ["Access pattern", "Choose model", "Choose key", "Bound query"], "steps": ["Start with the exact lookup: fetch the current session by ID.", "A key-value model fits a direct lookup without joins.", "Choose a high-entropy session key and an expiry policy.", "Retrieve one bounded value; unrelated sessions do not need scanning."], "pitfall": "Flexible documents do not remove the need to validate fields, manage migrations, and preserve invariants.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=NoSQL%3A%20key-value%2C%20document%2C%20column%20%26%20graph%20explained%20computer%20science", "takeaway": "Flexible documents do not remove the need to validate fields, manage migrations, and preserve invariants."}, {"id": "replication-consistency-cap-base", "module": "databases", "title": "Replication, consistency, CAP & BASE", "level": "Foundation", "concept": "Replication copies data across nodes for availability and read capacity. Leader-follower routes writes through a leader and may serve stale reads from asynchronous followers. Multi-leader and leaderless approaches introduce conflict handling and quorum trade-offs. Read-your-own-writes is a session guarantee, not something all replicas automatically provide.", "deep": "CAP applies during a network partition: a system cannot guarantee both linearizable consistency and availability for every request. It does not mean casually choosing any two of three at all times. Eventual consistency means replicas converge if updates stop and communication succeeds; it does not define a maximum delay. BASE is a design slogan, not a precise substitute for documented consistency semantics.", "examples": ["After changing a profile on the leader, a follower read may briefly show the old name; pin the session or use a version barrier.", "During a partition, a bank may reject some writes to preserve a single correct balance rather than accept conflicting updates."], "nodes": ["Write leader", "Commit", "Async replication", "Follower catches up"], "steps": ["The client submits a change to the leader.", "The leader commits under its configured durability policy.", "A lagging follower can still serve the previous value.", "Replication applies the update and the follower converges."], "pitfall": "Replication is not backup: accidental deletion can replicate successfully to every node.", "minutes": 10, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Replication%2C%20consistency%2C%20CAP%20%26%20BASE%20explained%20computer%20science", "takeaway": "Replication is not backup: accidental deletion can replicate successfully to every node."}, {"id": "sharding-routing-rebalancing", "module": "databases", "title": "Sharding, routing & rebalancing", "level": "Intermediate", "concept": "Sharding partitions rows across independently served data groups. Range sharding groups adjacent keys; hash sharding spreads keys by hash; directory sharding consults a location map. Vertical partitioning separates columns or responsibilities instead. A good shard key combines distribution, query locality, and growth behavior; high cardinality alone does not prevent a large tenant from becoming a hotspot.", "deep": "Applications, proxies, or lookup services route requests to shards. Cross-shard joins, transactions, secondary indexes, and globally unique IDs become harder. Rebalancing needs a migration protocol: copy data, capture changes, validate, switch routing, and retire old ownership safely. Consistent hashing with virtual nodes can reduce remapping, but it does not implement migration correctness. Systems such as Vitess and Citus automate selected parts of this problem.", "examples": ["Hash customer_id to spread independent customer records, keeping one customer’s orders colocated where practical.", "Range-sharding monotonically increasing timestamps sends all new writes to the newest range unless further distributed."], "nodes": ["Customer key", "Routing function", "Shard owner", "Migration check"], "steps": ["Extract the shard key from a request.", "Use a stable hash or directory entry to locate ownership.", "Send the operation to the shard responsible for that key.", "During rebalancing, honor ownership versions and verify copied data before cutover."], "pitfall": "Dual writes during migration can diverge unless retries, ordering, conflicts, and cutover rules are explicitly handled.", "minutes": 11, "references": [["PostgreSQL documentation", "https://www.postgresql.org/docs/current/"], ["Transaction isolation", "https://www.postgresql.org/docs/current/transaction-iso.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Sharding%2C%20routing%20%26%20rebalancing%20explained%20computer%20science", "takeaway": "Dual writes during migration can diverge unless retries, ordering, conflicts, and cutover rules are explicitly handled."}, {"id": "cache-layers-write-strategies", "module": "caching", "title": "Cache layers & write strategies", "level": "Foundation", "concept": "A cache keeps reusable results closer to consumers: browser, CDN, reverse proxy, in-process, or distributed cache. Cache-aside lets the application load misses from storage and populate the cache. Read-through delegates that loading to the cache layer. Write-through updates storage through the cache path; write-back acknowledges cached changes before asynchronously persisting them; write-around bypasses the cache for writes.", "deep": "Choose a source of truth and explicit freshness requirements. Cache-aside commonly invalidates a key after a committed update, but races can reinsert stale values. Write-back needs durable buffering and recovery or acknowledged writes may be lost. Cache keys must include all inputs affecting the answer, including tenant, permissions where relevant, locale, and schema/model version.", "examples": ["Product read: check Redis; on miss load PostgreSQL, store a bounded-TTL value, and return it.", "CDN: cache public versioned images near users, but avoid sharing personalized account responses across users."], "nodes": ["Application", "Cache lookup", "Database miss path", "Populate & return"], "steps": ["Build a key that identifies the exact representation.", "Read the cache: a hit can avoid database work.", "On a miss, fetch from the source of truth and handle not-found deliberately.", "Store the result with a bounded freshness policy, then return it."], "pitfall": "A cache is not automatically safe for authorization-sensitive data; keys and invalidation must preserve isolation.", "minutes": 11, "references": [["Redis documentation", "https://redis.io/docs/latest/"], ["FAISS documentation", "https://faiss.ai/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Cache%20layers%20%26%20write%20strategies%20explained%20computer%20science", "takeaway": "A cache is not automatically safe for authorization-sensitive data; keys and invalidation must preserve isolation."}, {"id": "lru-lfu-fifo-ttl-invalidation", "module": "caching", "title": "LRU, LFU, FIFO, TTL & invalidation", "level": "Foundation", "concept": "Eviction decides what leaves when capacity is limited. LRU removes the least recently used item; LFU removes a low-frequency item; FIFO removes the oldest inserted item. TTL expires values by age, addressing freshness rather than choosing the best victim under capacity pressure. A practical cache may combine expiry and eviction policies.", "deep": "An LRU design commonly combines a hash map with a doubly linked list: lookup finds a node and moves it to the newest end in O(1). Invalidation needs domain knowledge: changing a product may invalidate its detail key and several derived category pages. Versioned keys simplify some invalidation, while broad flushes can create load spikes. Measure hit ratio alongside miss cost and correctness.", "examples": ["Capacity two: read A, read B, read A, add C. LRU evicts B because A was recently used.", "Weather cached for 60 seconds expires even with spare memory because age, not capacity, determines freshness."], "nodes": ["Cache [A,B]", "Access A", "Order [B,A]", "Insert C, evict B"], "steps": ["The cache contains two keys with A older than B.", "A hit makes A the most recently used entry.", "The recency list is now B then A.", "Adding C exceeds capacity, so evict B and retain A,C."], "pitfall": "TTL is a freshness bound only under the defined loading and invalidation behavior; it is not a consistency protocol.", "minutes": 11, "references": [["Redis documentation", "https://redis.io/docs/latest/"], ["FAISS documentation", "https://faiss.ai/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=LRU%2C%20LFU%2C%20FIFO%2C%20TTL%20%26%20invalidation%20explained%20computer%20science", "takeaway": "TTL is a freshness bound only under the defined loading and invalidation behavior; it is not a consistency protocol."}, {"id": "stampedes-penetration-avalanche-bloom-filters", "module": "caching", "title": "Stampedes, penetration, avalanche & Bloom filters", "level": "Intermediate", "concept": "A stampede occurs when many clients rebuild the same expired value. Penetration repeatedly requests keys that do not exist and bypasses useful cache hits. An avalanche is a broad burst of misses, often after correlated expiry or a cache outage. These patterns overload the underlying store even when the average cache hit rate usually looks excellent.", "deep": "Use request coalescing or a per-key rebuild lock for hot misses; serve bounded stale data only if the domain permits. Cache negative results briefly for absent keys. A Bloom filter answers definitely absent or possibly present with false positives but no false negatives under correct construction; it does not replace validation. TTL jitter spreads expirations; probabilistic early refresh can refresh hot keys before they all expire.", "examples": ["One thousand requests hit the same expired homepage: single-flight lets one rebuild while the others wait or use bounded stale content.", "Random nonexistent IDs are rejected by a maintained Bloom filter before expensive database lookups when definitely absent."], "nodes": ["Hot key expires", "Many callers", "One rebuild owner", "Shared fresh value"], "steps": ["A popular value reaches its expiry.", "Concurrent misses would normally all query the origin.", "A per-key coalescing mechanism chooses one bounded rebuild.", "Publish the result and release waiters; handle owner failure and timeouts."], "pitfall": "Bloom filters can return false positives. A stale or incorrectly maintained filter can invalidate assumptions about absence.", "minutes": 11, "references": [["Redis documentation", "https://redis.io/docs/latest/"], ["FAISS documentation", "https://faiss.ai/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Stampedes%2C%20penetration%2C%20avalanche%20%26%20Bloom%20filters%20explained%20computer%20science", "takeaway": "Bloom filters can return false positives. A stale or incorrectly maintained filter can invalidate assumptions about absence."}, {"id": "redis-memory-serialization-vector-caches", "module": "caching", "title": "Redis memory, serialization & vector caches", "level": "Intermediate", "concept": "Redis stores structured values in memory; strings, hashes, lists, sets, sorted sets, and streams have different overheads. maxmemory and an eviction policy control memory pressure, while RDB snapshots and AOF have different persistence trade-offs. Serialization adds CPU and bytes: JSON is interoperable, MessagePack and Protobuf can be compact, and Python pickle must never consume untrusted input.", "deep": "For embedding or vector-result caches, key by normalized query, model version, index version, and relevant filters. A float32 vector of dimension d uses roughly 4d raw bytes before container overhead; float16 and int8 reduce that footprint but can affect quality. Reducing copies and batching can matter more than changing serializers. Benchmark memory, accuracy, latency, and hit ratio together.", "examples": ["A 768-dimensional float32 vector has 3,072 raw bytes; one million vectors need about 3.07 GB before metadata and indexes.", "After changing the embedding model, change the cache key version so old results are not silently reused."], "nodes": ["Query + versions", "Cache key", "Stored vector/result", "Expiry or refresh"], "steps": ["Collect every input that changes the semantic answer.", "Hash a canonical encoding of the query, filters, and model/index versions.", "Store a compact representation while measuring actual memory overhead.", "Expire or version out entries after source/model changes and monitor quality."], "pitfall": "Raw vector bytes are only part of total memory. Redis object overhead, copies, and index structures also count.", "minutes": 11, "references": [["Redis documentation", "https://redis.io/docs/latest/"], ["FAISS documentation", "https://faiss.ai/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Redis%20memory%2C%20serialization%20%26%20vector%20caches%20explained%20computer%20science", "takeaway": "Raw vector bytes are only part of total memory. Redis object overhead, copies, and index structures also count."}, {"id": "faiss-flat-ivf-hnsw-pq", "module": "caching", "title": "FAISS: Flat, IVF, HNSW & PQ", "level": "Advanced", "concept": "Vector indexes trade retrieval quality, latency, build cost, and memory. Flat search compares against every vector and gives exact results for the chosen metric. IVF partitions the space and searches selected cells. HNSW explores a proximity graph. Product quantization compresses vectors into codes so many distance operations use compact approximations.", "deep": "IVF needs representative training and an appropriate search-probe count. HNSW’s graph consumes memory and its search breadth controls recall and work. PQ saves memory at an accuracy cost. Measure recall against an exact baseline on representative queries, including filters and distribution shift. Some FAISS indexes support memory-mapped storage options, but support and performance are index-specific; mapping a file does not make all access free of RAM and I/O costs.", "examples": ["Flat: search 10,000 vectors exactly when the dataset is small enough for the latency budget.", "IVF: probe 10 of 100 coarse cells, then increase probes to trade extra work for better recall."], "nodes": ["Query vector", "Candidate routing", "Distance scoring", "Top-k results"], "steps": ["Normalize the query consistently with the training/index pipeline.", "Select cells or graph candidates using the chosen index.", "Compute exact or approximate distances depending on representation.", "Return top-k and compare recall with a Flat baseline during evaluation."], "pitfall": "Approximate nearest neighbors can miss true neighbors. Report recall as well as speed.", "minutes": 11, "references": [["Redis documentation", "https://redis.io/docs/latest/"], ["FAISS documentation", "https://faiss.ai/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=FAISS%3A%20Flat%2C%20IVF%2C%20HNSW%20%26%20PQ%20explained%20computer%20science", "takeaway": "Approximate nearest neighbors can miss true neighbors. Report recall as well as speed."}, {"id": "hashing-encryption-signatures-pki", "module": "security", "title": "Hashing, encryption, signatures & PKI", "level": "Foundation", "concept": "Hashing produces a fixed-size digest and is not reversible encryption. Encryption protects confidentiality using a key. Symmetric encryption uses shared secret key material; asymmetric cryptography uses a public/private relationship. Digital signatures authenticate a message and detect changes: private key signs and public key verifies. A signature does not hide the signed message.", "deep": "PKI links public keys to identities through certificates and certificate authorities. Verification checks the chain, identity, validity, and applicable policy. Use established authenticated encryption and cryptographic libraries rather than designing protocols. Store keys in an appropriate secret-management system, scope access, rotate deliberately, and separate encryption at rest from TLS in transit.", "examples": ["Hash: compare a downloaded file’s digest against an authenticated expected digest to detect changes.", "Signature: a client verifies a release with the publisher’s public key without learning the publisher’s private key."], "nodes": ["Message", "Private-key signer", "Signature + message", "Public-key verifier"], "steps": ["The publisher prepares the exact release bytes.", "An approved signature algorithm uses the private key.", "Distribute the message and signature; the contents may remain public.", "Verify the signature with the trusted public key and reject modified bytes."], "pitfall": "Encoding is not encryption, and a digest without an authenticated reference does not establish who published a file.", "minutes": 10, "references": [["OWASP cheat sheets", "https://cheatsheetseries.owasp.org/"], ["JWT standard • RFC 7519", "https://www.rfc-editor.org/rfc/rfc7519"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Hashing%2C%20encryption%2C%20signatures%20%26%20PKI%20explained%20computer%20science", "takeaway": "Encoding is not encryption, and a digest without an authenticated reference does not establish who published a file."}, {"id": "jwts-hs256-rs256-claims-jwks", "module": "security", "title": "JWTs, HS256, RS256, claims & JWKS", "level": "Foundation", "concept": "A common signed JWT contains base64url-encoded header and payload plus a signature. The payload is readable, so do not put secrets in it. HS256 uses a shared secret: anyone able to verify with that secret can also sign. RS256 uses a private key to sign and a public key to verify, allowing services to verify without being able to mint tokens.", "deep": "Validate a fixed allowed algorithm, signature, expiration, issuer, audience, and applicable not-before rules. Claims such as iat and jti have meaning only when your system checks and uses them. JWKS distributes verification keys; rotate using key IDs with a safe overlap period and bounded cache policy. Do not trust an unverified token’s arbitrary key URL or accept alg:none. Authentication still needs resource-level authorization.", "examples": ["A token for audience billing must be rejected by the admin API even if its signature is valid.", "During RS256 rotation, publish the new public key before issuing new-key tokens and retain the old key until valid old tokens expire."], "nodes": ["Encoded token", "Allowed algorithm", "Signature & claims", "Authorization"], "steps": ["Parse the bounded token without treating its payload as trusted.", "Select only an explicitly allowed algorithm and trusted verification key.", "Verify signature plus exp, issuer, audience, and required claims.", "Use the authenticated identity to enforce permissions on the requested object."], "pitfall": "Decoding a JWT is not verification. A valid signature alone does not mean the token is valid for this API.", "minutes": 11, "references": [["OWASP cheat sheets", "https://cheatsheetseries.owasp.org/"], ["JWT standard • RFC 7519", "https://www.rfc-editor.org/rfc/rfc7519"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=JWTs%2C%20HS256%2C%20RS256%2C%20claims%20%26%20JWKS%20explained%20computer%20science", "takeaway": "Decoding a JWT is not verification. A valid signature alone does not mean the token is valid for this API."}, {"id": "sessions-token-storage-replay-revocation", "module": "security", "title": "Sessions, token storage, replay & revocation", "level": "Foundation", "concept": "A server session typically keeps authoritative login state behind an opaque identifier. Self-contained access tokens carry signed claims but make immediate revocation harder. Bearer credentials can be replayed by anyone who steals them. Short lifetimes reduce exposure; refresh-token rotation with reuse detection helps catch stolen refresh credentials.", "deep": "HttpOnly+Secure cookies reduce direct JavaScript token theft, while SameSite and explicit CSRF defenses address browser credential sending. XSS can still trigger authenticated actions. localStorage is readable by injected scripts. Revocation can use bounded denylist entries keyed by jti, a session/token version, or authoritative session lookups. DPoP or mTLS can bind credentials to keys in suitable systems, but add deployment and client complexity.", "examples": ["Logout revokes a server session immediately; a standalone access JWT may remain usable until expiry unless the API checks revocation.", "Refresh token R1 is exchanged for R2; later reuse of R1 triggers family revocation and reauthentication."], "nodes": ["Login", "Issue short access", "Rotate refresh", "Detect reuse"], "steps": ["Authenticate through a protected login flow.", "Issue a short-lived access credential and protect the refresh credential.", "Consume the old refresh token atomically and mint a new one.", "Reject a reused consumed token and apply the session-family recovery policy."], "pitfall": "Token storage choices involve XSS and CSRF trade-offs. HttpOnly does not make an application immune to XSS.", "minutes": 10, "references": [["OWASP cheat sheets", "https://cheatsheetseries.owasp.org/"], ["JWT standard • RFC 7519", "https://www.rfc-editor.org/rfc/rfc7519"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Sessions%2C%20token%20storage%2C%20replay%20%26%20revocation%20explained%20computer%20science", "takeaway": "Token storage choices involve XSS and CSRF trade-offs. HttpOnly does not make an application immune to XSS."}, {"id": "oauth-2-0-oidc-sso-authorization", "module": "security", "title": "OAuth 2.0, OIDC, SSO & authorization", "level": "Intermediate", "concept": "OAuth 2.0 delegates access to resources; OpenID Connect adds an authentication layer and ID tokens. Authorization Code with PKCE binds the code exchange to a client-generated verifier. Client Credentials serves machine-to-machine access without an end-user login. SSO reuses an identity provider’s session across applications, subject to consent and organizational policy.", "deep": "Distinguish access tokens for APIs, ID tokens for the client’s login context, and refresh tokens for obtaining new access. Validate redirects, state, nonce where applicable, issuer, audience, and token claims. RBAC grants permissions through roles; ABAC evaluates attributes such as ownership, tenant, and environment. Enforce authorization server-side on every object operation, not merely by hiding a UI button.", "examples": ["A photo-printing app receives permission to read selected photos without learning the user’s identity-provider password.", "An accounts role can view invoices, but ABAC also requires the invoice tenant to match the caller’s tenant."], "nodes": ["Client + PKCE", "Identity provider", "Code exchange", "API access"], "steps": ["The client creates a verifier and sends its challenge in the authorization request.", "The user authenticates and the provider returns a short-lived authorization code.", "The client exchanges the code with its original verifier and validated redirect binding.", "Use the access token for its intended API; keep ID-token purposes separate."], "pitfall": "An ID token is not automatically an API access token. Check the intended recipient and protocol role.", "minutes": 10, "references": [["OWASP cheat sheets", "https://cheatsheetseries.owasp.org/"], ["JWT standard • RFC 7519", "https://www.rfc-editor.org/rfc/rfc7519"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=OAuth%202.0%2C%20OIDC%2C%20SSO%20%26%20authorization%20explained%20computer%20science", "takeaway": "An ID token is not automatically an API access token. Check the intended recipient and protocol role."}, {"id": "passwords-owasp-risks-secrets", "module": "security", "title": "Passwords, OWASP risks & secrets", "level": "Foundation", "concept": "Passwords need slow, salted password hashing such as Argon2id, bcrypt, or scrypt, with parameters appropriate to the deployment. A unique salt prevents equal passwords sharing equal stored hashes; an optional pepper is a separately protected secret. Fast general hashes alone are unsuitable for password storage because attackers can test guesses rapidly offline.", "deep": "Prevent SQL injection with parameterized queries. Reduce XSS with output encoding and safe rendering. Use CSRF protections for browser-authenticated mutations, object-level checks against IDOR, and tightly controlled outbound requests against SSRF. Secrets belong outside source code and logs, with least privilege and rotation. Use the current OWASP resources as a risk framework rather than treating a named list as a complete security specification.", "examples": ["SQL: bind the username as a parameter instead of concatenating it into a WHERE clause.", "IDOR: /invoices/42 must check ownership or role even if invoice IDs are difficult to guess."], "nodes": ["Untrusted input", "Boundary validation", "Authorization", "Safe operation"], "steps": ["Treat user fields, URLs, and object IDs as untrusted.", "Validate structure and use context-specific encoding or parameter binding.", "Check the authenticated caller’s permission on the exact resource.", "Perform the operation with scoped credentials and record safe audit context."], "pitfall": "Validation alone does not prevent SQL injection, and unpredictable IDs do not replace authorization.", "minutes": 11, "references": [["OWASP cheat sheets", "https://cheatsheetseries.owasp.org/"], ["JWT standard • RFC 7519", "https://www.rfc-editor.org/rfc/rfc7519"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Passwords%2C%20OWASP%20risks%20%26%20secrets%20explained%20computer%20science", "takeaway": "Validation alone does not prevent SQL injection, and unpredictable IDs do not replace authorization."}, {"id": "queues-pub-sub-event-streaming", "module": "messaging", "title": "Queues, pub/sub & event streaming", "level": "Foundation", "concept": "A work queue distributes tasks among workers so one logical task is handled by an eligible consumer. Pub/sub broadcasts events to interested subscribers. An event stream retains ordered records for replay, often partitioned for scale. These models can coexist, but their retention, delivery, replay, and consumer coordination semantics differ.", "deep": "RabbitMQ provides messaging with exchanges, queues, routing, and acknowledgements. SQS provides managed queue semantics with visibility timeouts; queue type affects ordering and deduplication. Kinesis is a managed partitioned stream. Choose by replay needs, routing, throughput, ordering scope, failure recovery, and operational budget. Brokers buffer load but cannot fix an indefinitely slower downstream service.", "examples": ["Work queue: three image workers divide uploaded-image resize tasks.", "Pub/sub: both analytics and email services react to an order-created event independently."], "nodes": ["Producer", "Broker", "Consumer A", "Acknowledgement"], "steps": ["The producer publishes a task with a stable identifier.", "The broker retains and offers it under its durability contract.", "One eligible worker handles this work-queue task.", "Acknowledge only after the effect is safe; a crash before acknowledgement can cause redelivery."], "pitfall": "Queue, pub/sub, and retained stream are not interchangeable contracts. Confirm replay and acknowledgement behavior.", "minutes": 10, "references": [["Apache Kafka documentation", "https://kafka.apache.org/documentation/"], ["Celery user guide", "https://docs.celeryq.dev/en/stable/userguide/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Queues%2C%20pub/sub%20%26%20event%20streaming%20explained%20computer%20science", "takeaway": "Queue, pub/sub, and retained stream are not interchangeable contracts. Confirm replay and acknowledgement behavior."}, {"id": "kafka-topics-partitions-groups-offsets", "module": "messaging", "title": "Kafka: topics, partitions, groups & offsets", "level": "Foundation", "concept": "Kafka stores records in named topics split into ordered partitions. Producers append records, often using a key to select a partition. Consumers track offsets, which identify positions within a partition. Within a consumer group, each partition is assigned to one consumer at a time during a stable assignment; separate groups can independently read the same topic.", "deep": "Ordering is per partition, not global across the topic. More consumers than assigned partitions do not increase that group’s parallelism. Retention is separate from consumption, enabling replay. Replication, acknowledgement configuration, and in-sync replica settings affect durability. Rebalances move ownership, so process shutdown and offset commits carefully. A partition key should preserve required ordering without creating a hot partition.", "examples": ["Key by order_id so one order’s events stay in partition order; unrelated orders can process in parallel.", "Analytics and billing use different consumer groups, each keeping independent offsets for the same event stream."], "nodes": ["Producer key=42", "Topic partition 0", "Group worker A", "Commit offset"], "steps": ["The producer chooses a partition based on the record key and partitioner.", "The record is appended at a specific partition offset.", "The group’s assigned worker reads records from that partition in order.", "Commit progress after the intended processing boundary; replay may occur after a crash."], "pitfall": "Kafka ordering is per partition. Exactly-once Kafka processing does not automatically make external side effects exactly once.", "minutes": 11, "references": [["Apache Kafka documentation", "https://kafka.apache.org/documentation/"], ["Celery user guide", "https://docs.celeryq.dev/en/stable/userguide/"]], "video": ["-RDyEFvnTXI", "Apache Kafka fundamentals", "ByteByteGo"], "searchVideo": "https://www.youtube.com/results?search_query=Kafka%3A%20topics%2C%20partitions%2C%20groups%20%26%20offsets%20explained%20computer%20science", "takeaway": "Kafka ordering is per partition. Exactly-once Kafka processing does not automatically make external side effects exactly once."}, {"id": "delivery-guarantees-idempotency-dead-letters", "module": "messaging", "title": "Delivery guarantees, idempotency & dead letters", "level": "Foundation", "concept": "At-most-once can lose work but avoids redelivery; at-least-once retries until acknowledgement and may duplicate work. Exactly-once is meaningful only for a defined boundary, such as a transaction coordinating consumed offsets and produced records. An external charge is not automatically part of that boundary. Idempotent consumers make repeated delivery safe.", "deep": "Store an event ID with its business effect under one atomic constraint where possible. Retry transient failures with capped backoff and jitter; permanent validation failures should not loop forever. A dead-letter queue isolates exhausted messages for inspection and controlled replay. Include safe error context and original identifiers, and monitor DLQ growth rather than treating it as successful processing.", "examples": ["A worker updates inventory then crashes before ack; redelivery must not subtract stock a second time.", "An invalid email payload moves to a DLQ after classification instead of retrying every second indefinitely."], "nodes": ["Deliver event E", "Check processed ID", "Commit effect + ID", "Ack"], "steps": ["The broker delivers a record that may have been delivered earlier.", "Look up E under a transactional uniqueness guard.", "For a new E, commit the effect and processed marker together.", "Acknowledge; if delivery repeats later, the marker prevents a duplicate effect."], "pitfall": "A processed marker committed before the business effect can lose work; commit them atomically when they share a database.", "minutes": 10, "references": [["Apache Kafka documentation", "https://kafka.apache.org/documentation/"], ["Celery user guide", "https://docs.celeryq.dev/en/stable/userguide/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Delivery%20guarantees%2C%20idempotency%20%26%20dead%20letters%20explained%20computer%20science", "takeaway": "A processed marker committed before the business effect can lose work; commit them atomically when they share a database."}, {"id": "celery-worker-pools-compute-heavy-jobs", "module": "messaging", "title": "Celery, worker pools & compute-heavy jobs", "level": "Foundation", "concept": "A queued job separates quick API admission from slow execution. In Celery, the application publishes through a broker, workers execute tasks, and an optional result backend stores state/results. Prefork worker processes suit Python CPU work and isolate interpreters. Thread or cooperative pools can fit selected I/O workloads, subject to task/library compatibility.", "deep": "Return a task ID and expose polling or progress events. Bound concurrency by CPU, memory, GPU capacity, and downstream limits; loading a large model per process multiplies memory. Separate queues for LLM, search, and scraping workloads avoid one class starving the others. acks_late and time limits change failure behavior but do not replace idempotency. For durable progress, store authoritative job state outside a single worker’s memory.", "examples": ["An API enqueues a report in 30 ms and returns 202; a worker spends 40 seconds generating it.", "A model worker loads weights once at startup and batches requests instead of reloading for each task."], "nodes": ["FastAPI producer", "Broker queue", "Celery worker", "Result + progress"], "steps": ["Validate input, create a durable job record, and submit an identifier.", "The broker buffers waiting tasks under a configured persistence policy.", "A bounded worker executes the task and updates durable state.", "The client polls or subscribes; completion points to a stored result."], "pitfall": "Cancelling an HTTP request does not necessarily cancel a queued task. Define cancellation and result-retention behavior.", "minutes": 11, "references": [["Apache Kafka documentation", "https://kafka.apache.org/documentation/"], ["Celery user guide", "https://docs.celeryq.dev/en/stable/userguide/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Celery%2C%20worker%20pools%20%26%20compute-heavy%20jobs%20explained%20computer%20science", "takeaway": "Cancelling an HTTP request does not necessarily cancel a queued task. Define cancellation and result-retention behavior."}, {"id": "outbox-event-sourcing-cqrs", "module": "messaging", "title": "Outbox, event sourcing & CQRS", "level": "Intermediate", "concept": "The outbox pattern writes a domain change and an event record in one local database transaction. A relay later publishes outbox rows, eliminating the gap where a database commit succeeds but event publication fails. Relay retries can still duplicate messages, so consumers remain idempotent. An inbox can similarly record received event IDs.", "deep": "Event sourcing stores the event history as the authoritative record and derives current state by replay, often with snapshots. CQRS separates command and query models; it does not require event sourcing or separate databases. These designs add schema evolution, replay, ordering, and operational complexity. Use them when auditability or distinct read/write needs justify the cost, rather than as defaults.", "examples": ["Order transaction inserts both order 42 and OrderCreated(42) into the outbox; a relay publishes it after commit.", "A read projection builds daily sales totals from events and can be rebuilt after its calculation logic changes."], "nodes": ["Domain transaction", "Outbox row", "Relay publish", "Idempotent consumer"], "steps": ["Apply a business change inside one local transaction.", "Write the corresponding event to the outbox before committing.", "The relay publishes and marks progress; a crash can cause publication again.", "The consumer deduplicates the event and safely applies its effect."], "pitfall": "An outbox makes publication reliable, not instantaneous or automatically duplicate-free.", "minutes": 11, "references": [["Apache Kafka documentation", "https://kafka.apache.org/documentation/"], ["Celery user guide", "https://docs.celeryq.dev/en/stable/userguide/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Outbox%2C%20event%20sourcing%20%26%20CQRS%20explained%20computer%20science", "takeaway": "An outbox makes publication reliable, not instantaneous or automatically duplicate-free."}, {"id": "timeouts-exponential-backoff-jitter", "module": "resilience", "title": "Timeouts, exponential backoff & jitter", "level": "Foundation", "concept": "A timeout bounds waiting; a deadline bounds the total operation, including retries and nested calls. Retry only failures that may succeed later and only when repeating the operation is safe or protected by idempotency. Exponential backoff increases delay after each failure; jitter randomizes delay so many clients do not retry at exactly the same instant.", "deep": "Cap attempts, total elapsed time, and backoff. Honor meaningful Retry-After instructions. Propagate the remaining deadline to downstream calls. Avoid retries at every layer: three attempts at three layers can multiply into 27 leaf calls. A timeout means the caller stopped waiting, not that the server performed no effect. Use libraries such as tenacity or Resilience4j with an explicit policy.", "examples": ["Read retry delays might be sampled from 0–100 ms, then 0–200 ms, then 0–400 ms within a total deadline.", "After a payment timeout, reuse the original idempotency key rather than issuing a new payment request identity."], "nodes": ["Attempt 1 fails", "Classify failure", "Jittered delay", "Bounded retry"], "steps": ["The remote read reaches a timeout.", "Decide whether this failure is transient and whether repeating is safe.", "Choose a random delay within the capped backoff window.", "Retry only if attempts and remaining deadline permit, otherwise return a controlled failure."], "pitfall": "Never blindly retry non-idempotent effects; an earlier timed-out attempt may already have succeeded.", "minutes": 11, "references": [["Resilience4j documentation", "https://resilience4j.readme.io/docs"], ["Tenacity documentation", "https://tenacity.readthedocs.io/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Timeouts%2C%20exponential%20backoff%20%26%20jitter%20explained%20computer%20science", "takeaway": "Never blindly retry non-idempotent effects; an earlier timed-out attempt may already have succeeded."}, {"id": "circuit-breakers-bulkheads-fallbacks", "module": "resilience", "title": "Circuit breakers, bulkheads & fallbacks", "level": "Intermediate", "concept": "A circuit breaker stops repeatedly calling a dependency that is likely failing. Closed allows traffic and records outcomes; open fails fast; half-open permits limited probes to check recovery. Thresholds should use meaningful failure classification and sampling. A breaker is not the same as retrying and does not substitute for timeouts.", "deep": "Bulkheads allocate separate pools, queues, or concurrency limits so one dependency cannot consume every resource. Fallbacks provide acceptable degraded behavior, such as stale recommendations, when correctness allows. Define when a fallback is unavailable and monitor its use. Libraries such as Resilience4j or pybreaker help implement policies, but the application must decide which failures count and how probes recover.", "examples": ["If recommendation calls repeatedly time out, open the circuit and show a basic popular-products list.", "Give the shipping API a separate ten-slot concurrency budget so its outage does not exhaust payment workers."], "nodes": ["Closed", "Failures cross threshold", "Open", "Half-open probe"], "steps": ["Normal requests call the dependency and update a rolling health view.", "Enough qualifying failures trigger a state transition.", "Reject calls quickly for the cooldown rather than consuming timeout budgets.", "Allow limited probes; success closes the breaker, failure reopens it."], "pitfall": "A half-open state should limit probes; allowing every waiting client through can recreate overload.", "minutes": 10, "references": [["Resilience4j documentation", "https://resilience4j.readme.io/docs"], ["Tenacity documentation", "https://tenacity.readthedocs.io/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Circuit%20breakers%2C%20bulkheads%20%26%20fallbacks%20explained%20computer%20science", "takeaway": "A half-open state should limit probes; allowing every waiting client through can recreate overload."}, {"id": "resilient-scraping-incremental-ingestion", "module": "resilience", "title": "Resilient scraping & incremental ingestion", "level": "Intermediate", "concept": "A scraper is an ingestion service with unstable external dependencies. Prefer an official API or ordinary HTTP when available; browser automation is expensive and brittle. Respect site terms, robots guidance, access controls, and per-domain limits. Treat 429, 403, CAPTCHA, layout changes, and transport errors differently instead of retrying all failures identically.", "deep": "Use explicit waits rather than arbitrary sleeps, bounded browser pools, health checks, and cleanup to control leaks. Persist checkpoints, deduplicate content hashes, and process only changed records for incremental updates. Proxy routing can support permitted geographic or reliability needs; do not treat it as a way to bypass a site’s restrictions. Queue ingestion jobs, bound retries, and retain enough lineage to explain where each stored fact came from.", "examples": ["A daily import stores ETag and content hash; an unchanged page avoids parsing and duplicate inserts.", "A 429 pauses that domain according to Retry-After while workers continue permitted work for other domains."], "nodes": ["Scheduled URL", "Policy & throttle", "Fetch & detect change", "Checkpoint"], "steps": ["Choose an allowed URL and load its previous checkpoint.", "Apply per-domain concurrency and rate limits before fetching.", "Use conditional requests or content hashes to identify changes; classify failures.", "Upsert idempotently and persist progress so a crash can resume safely."], "pitfall": "Proxy rotation and browser automation do not remove the need to respect access restrictions and site policies.", "minutes": 11, "references": [["Resilience4j documentation", "https://resilience4j.readme.io/docs"], ["Tenacity documentation", "https://tenacity.readthedocs.io/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Resilient%20scraping%20%26%20incremental%20ingestion%20explained%20computer%20science", "takeaway": "Proxy rotation and browser automation do not remove the need to respect access restrictions and site policies."}, {"id": "thread-safety-producer-consumer-distributed-locks", "module": "performance", "title": "Thread safety, producer-consumer & distributed locks", "level": "Intermediate", "concept": "Producer-consumer systems decouple task creation from execution through a bounded buffer. Thread safety requires a clear ownership and synchronization policy for every shared invariant. Atomics suit individual operations; locks protect larger critical sections; concurrent containers protect their documented operations. Optimistic version checks detect stale updates, while pessimistic row locks prevent conflicting access before changes.", "deep": "Distributed locks add leases, clock assumptions, process pauses, and network failures. A lease may expire while an old holder still runs, so fencing tokens checked by the protected resource are often necessary. Redis or ZooKeeper can coordinate access, but guarantees depend on the protocol and failure model; Redlock is not a universal correctness shortcut. Prefer database constraints or idempotent operations when they directly express the invariant.", "examples": ["A bounded 100-item queue makes producers wait or reject rather than consuming unlimited RAM.", "A file writer with fencing token 8 must be rejected after a new owner obtains token 9, even if the old writer resumes."], "nodes": ["Producer", "Bounded queue", "Consumer pool", "Capacity feedback"], "steps": ["A producer attempts to enqueue one item.", "The queue accepts only while capacity remains.", "Workers take items and release buffer slots.", "When full, apply the documented wait, reject, or drop policy rather than unbounded growth."], "pitfall": "A distributed lock without fencing may not prevent a paused, expired owner from modifying the resource later.", "minutes": 11, "references": [["k6 documentation", "https://grafana.com/docs/k6/latest/"], ["Java Flight Recorder", "https://docs.oracle.com/en/java/javase/25/jfapi/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Thread%20safety%2C%20producer-consumer%20%26%20distributed%20locks%20explained%20computer%20science", "takeaway": "A distributed lock without fencing may not prevent a paused, expired owner from modifying the resource later."}, {"id": "latency-percentiles-throughput-profiling", "module": "performance", "title": "Latency percentiles, throughput & profiling", "level": "Foundation", "concept": "Throughput measures completed work per unit time; latency measures how long an operation takes. p50 is the median, p95 bounds 95 percent of observed values, and p99 exposes slower tail behavior. An average can look healthy while a minority of users wait seconds. Queueing increases sharply near saturation, so report load and error rate with timing.", "deep": "Establish a representative baseline, instrument where time goes, change one cause, and compare under similar conditions. Use cProfile, py-spy, Java Flight Recorder, query statistics, or traces as appropriate. Distinguish CPU time from waiting and separate network setup, database, serialization, and application work. A claimed 50 ms to 15 ms improvement needs reproducible measurements, sample size, workload, and percentile context.", "examples": ["Nine requests take 10 ms and one takes 1,000 ms: median is fast, but the tail and mean reveal the slow experience.", "A trace attributes 35 of 50 ms to repeated SQL calls; batching can remove round trips instead of micro-optimizing JSON."], "nodes": ["Baseline", "Measure breakdown", "Change one cause", "Compare under load"], "steps": ["Record latency distribution, throughput, errors, and resource use.", "Find the dominant span or profiler stack rather than guessing.", "Make a targeted change, preserving the same correctness requirements.", "Repeat a comparable workload and check tails, not only the best run."], "pitfall": "Do not average p99 values from separate windows as though that produced the global p99; aggregate distributions appropriately.", "minutes": 11, "references": [["k6 documentation", "https://grafana.com/docs/k6/latest/"], ["Java Flight Recorder", "https://docs.oracle.com/en/java/javase/25/jfapi/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Latency%20percentiles%2C%20throughput%20%26%20profiling%20explained%20computer%20science", "takeaway": "Do not average p99 values from separate windows as though that produced the global p99; aggregate distributions appropriately."}, {"id": "load-testing-batching-connection-reuse", "module": "performance", "title": "Load testing, batching & connection reuse", "level": "Intermediate", "concept": "Load tests explore behavior under a controlled workload, not just the maximum requests a laptop can generate. k6, Locust, and JMeter can model arrivals, user flows, data variety, and failures. Closed-loop users wait for responses before sending more; open-loop arrival models expose overload differently. The load generator itself must not become the bottleneck.", "deep": "Batching amortizes per-call overhead but may add waiting time and produce larger failure units. Connection pooling and keep-alive avoid repeated setup but require limits, timeouts, and stale-connection handling. Payload compression trades CPU for bandwidth. Test realistic cold/warm caches, data sizes, slow dependencies, and time budgets, then identify the first saturated resource.", "examples": ["Batch 100 inserts in one transaction to reduce round trips while retaining a safe bounded batch size.", "Reuse an HTTPS connection for ten calls instead of repeating DNS/TCP/TLS setup for every call."], "nodes": ["Workload model", "Ramp arrivals", "Observe saturation", "Tune & retest"], "steps": ["Define endpoints, payloads, arrival rate, and acceptable latency/errors.", "Increase offered load gradually while checking generator health.", "Watch queues, CPU, pools, database locks, and p95/p99 latency.", "Change the limiting factor and retest at the same load and data conditions."], "pitfall": "A benchmark with only hot cache hits does not establish database capacity for cold or invalidated traffic.", "minutes": 10, "references": [["k6 documentation", "https://grafana.com/docs/k6/latest/"], ["Java Flight Recorder", "https://docs.oracle.com/en/java/javase/25/jfapi/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Load%20testing%2C%20batching%20%26%20connection%20reuse%20explained%20computer%20science", "takeaway": "A benchmark with only hot cache hits does not establish database capacity for cold or invalidated traffic."}, {"id": "monoliths-microservices-architectural-boundaries", "module": "architecture", "title": "Monoliths, microservices & architectural boundaries", "level": "Foundation", "concept": "A monolith deploys as one unit; a modular monolith keeps strong internal boundaries within that deployment. Microservices separate deployments and ownership around capabilities, adding network calls, distributed data, and operational overhead. MVC separates presentation/control/model concerns; clean or hexagonal architecture makes domain logic independent of external adapters where useful.", "deep": "Domain-driven design uses business language, aggregates, and bounded contexts to make ownership explicit. Start from cohesion and invariants rather than service count. The 12-factor principles offer deployment conventions such as external configuration and disposable processes. A BFF adapts APIs to a particular client experience. A small team can often get clearer boundaries and simpler consistency from a modular monolith before distributing services.", "examples": ["A commerce monolith separates catalog, checkout, and billing modules while committing local order changes transactionally.", "A high-volume video transcoder becomes a separate service because its scaling and resource requirements differ from account APIs."], "nodes": ["Client", "Module interface", "Domain rules", "Storage adapter"], "steps": ["The client reaches a stable application entry point.", "A module accepts a use case without exposing internal tables.", "Domain logic enforces invariants and expresses required ports.", "Adapters implement database or messaging access without owning the business rule."], "pitfall": "Microservices do not automatically create good boundaries; poorly chosen boundaries become expensive network coupling.", "minutes": 11, "references": [["AWS saga guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html"], ["Transactional outbox guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Monoliths%2C%20microservices%20%26%20architectural%20boundaries%20explained%20computer%20science", "takeaway": "Microservices do not automatically create good boundaries; poorly chosen boundaries become expensive network coupling."}, {"id": "api-gateways-discovery-sync-async-calls", "module": "architecture", "title": "API gateways, discovery & sync/async calls", "level": "Intermediate", "concept": "An API gateway fronts services and can handle routing, authentication integration, rate limits, and protocol adaptation. Service discovery maps a logical service name to healthy endpoints through DNS, a registry, or a platform. Consul and Eureka are examples of registry-oriented tooling. Gateways and discovery solve different problems.", "deep": "Synchronous calls make response dependencies immediate and easy to follow but couple latency and availability. Asynchronous messages decouple timing while introducing delivery, ordering, and eventual-consistency concerns. Propagate identity safely, use deadlines, and avoid putting all business logic in the gateway. A BFF can aggregate for one client, but overly chatty service graphs can multiply tail latency and failure probability.", "examples": ["The gateway sends /catalog to catalog instances and /billing to billing instances after validating the caller.", "Order creation commits quickly and publishes an email event instead of waiting synchronously for the email provider."], "nodes": ["Client", "Gateway", "Service discovery", "Healthy service"], "steps": ["Accept the client request at a controlled edge.", "Apply routing and shared edge policy while preserving request context.", "Resolve the logical service to eligible endpoints.", "Call with a deadline, handle failures, and keep resource authorization in the service."], "pitfall": "A health-check passing does not prove every downstream dependency is healthy; avoid routing based on superficial checks alone.", "minutes": 10, "references": [["AWS saga guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html"], ["Transactional outbox guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=API%20gateways%2C%20discovery%20%26%20sync/async%20calls%20explained%20computer%20science", "takeaway": "A health-check passing does not prove every downstream dependency is healthy; avoid routing based on superficial checks alone."}, {"id": "two-phase-commit-sagas-compensation", "module": "architecture", "title": "Two-phase commit, sagas & compensation", "level": "Intermediate", "concept": "Two-phase commit coordinates one distributed commit across prepared participants: first prepare, then commit or abort. Prepared participants can hold locks while awaiting a coordinator decision, so failure can block progress. A saga instead sequences local transactions with compensating actions and accepts intermediate states. Compensation is a new business action, not time travel or an automatic SQL rollback.", "deep": "Orchestration uses a coordinator to track steps and recovery; choreography lets participants react to events, distributing flow logic. Design each step and compensation to be idempotent and observable, including what happens when compensation itself fails. XA is a distributed transaction interface; TCC reserves then confirms/cancels business resources. Three-phase commit has additional assumptions and is not a general escape from distributed-failure trade-offs.", "examples": ["Order saga: reserve stock, charge payment, schedule delivery; if charging fails, release the stock reservation.", "A refund compensates a settled charge but may take time, incur fees, or fail and need human recovery."], "nodes": ["Reserve stock", "Charge fails", "Release reservation", "Order cancelled"], "steps": ["Create a durable order workflow and reserve inventory locally.", "The payment step returns a definitive failure or is reconciled after an unknown outcome.", "Run the idempotent release compensation for the inventory reservation.", "Record a terminal cancelled state only after required recovery is confirmed."], "pitfall": "Unknown payment outcomes require reconciliation; blindly compensating and retrying can create incorrect financial effects.", "minutes": 11, "references": [["AWS saga guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html"], ["Transactional outbox guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Two-phase%20commit%2C%20sagas%20%26%20compensation%20explained%20computer%20science", "takeaway": "Unknown payment outcomes require reconciliation; blindly compensating and retrying can create incorrect financial effects."}, {"id": "erp-integrity-ledgers-audit-trails", "module": "architecture", "title": "ERP integrity, ledgers & audit trails", "level": "Intermediate", "concept": "Business workflows must preserve invariants across orders, inventory, invoices, and ledgers. Use numeric decimal types for money, database constraints for uniqueness and bounds, and transactions for local atomicity. An append-oriented ledger records movements rather than repeatedly overwriting an unexplained balance. Double-entry accounting represents balanced debits and credits under a defined chart of accounts.", "deep": "Use stable operation references, optimistic versions for stale edits, and explicit lifecycle transitions. Reject duplicate requests atomically rather than checking and hoping no concurrent insert occurs. An audit trail should identify actor, time, operation, and meaningful change context while protecting sensitive data and preventing ordinary mutation. For distributed steps, combine local integrity with outbox events and compensations; do not pretend one local transaction covers external systems.", "examples": ["Two payment submissions with the same operation ID hit a unique constraint, so only one ledger movement is committed.", "An approved invoice cannot be edited in place; a correction creates a reversal or authorized revision with audit history."], "nodes": ["Validate transition", "Lock/version check", "Balanced entries", "Atomic commit"], "steps": ["Check that the requested lifecycle transition is allowed for the actor.", "Guard the current version and any balance-sensitive rows.", "Create the required balanced ledger entries and audit record.", "Commit the operation reference and all local effects together, or roll back."], "pitfall": "A cached balance is not an independent source of truth; reconcile derived balances with the authoritative ledger.", "minutes": 11, "references": [["AWS saga guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html"], ["Transactional outbox guidance", "https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=ERP%20integrity%2C%20ledgers%20%26%20audit%20trails%20explained%20computer%20science", "takeaway": "A cached balance is not an independent source of truth; reconcile derived balances with the authoritative ledger."}, {"id": "scaling-load-balancing-proxies", "module": "systems", "title": "Scaling, load balancing & proxies", "level": "Foundation", "concept": "Vertical scaling gives one machine more resources; horizontal scaling adds machines. Stateless request handlers are easier to spread across replicas, but shared data and coordination remain bottlenecks. L4 load balancing works with transport information; L7 can inspect HTTP routes and headers. A reverse proxy fronts servers; a forward proxy acts on behalf of clients.", "deep": "Round robin cycles through eligible backends. Weighted round robin accounts for unequal capacity; least connections favors fewer active connections but does not directly measure CPU cost. IP hashing can provide affinity but is sensitive to shared NAT addresses and membership changes. Nginx, HAProxy, and managed application load balancers implement different capabilities. Use health checks, graceful draining, and bounded upstream timeouts.", "examples": ["Round robin sends requests 1,2,3,4 to A,B,C,A when all three servers are healthy.", "Route /images through a CDN and /api through application servers using an L7 proxy."], "nodes": ["Request", "Load balancer", "Selected backend", "Health feedback"], "steps": ["A client sends one request to the service address.", "The balancer filters eligible backends and applies its routing algorithm.", "The selected backend processes the request with its own capacity limits.", "Failures or draining status update future eligibility rather than guaranteeing the current call succeeds."], "pitfall": "Adding API replicas does not increase a saturated database’s write capacity.", "minutes": 11, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Scaling%2C%20load%20balancing%20%26%20proxies%20explained%20computer%20science", "takeaway": "Adding API replicas does not increase a saturated database’s write capacity."}, {"id": "slis-slos-slas-capacity-estimates", "module": "systems", "title": "SLIs, SLOs, SLAs & capacity estimates", "level": "Foundation", "concept": "An SLI measures service behavior, such as the fraction of successful requests below 300 ms. An SLO sets an internal target for an SLI over a window. An SLA is an external commitment with defined consequences. Availability depends on what counts as success, whose traffic is counted, and which window is used; a single percentage without scope is incomplete.", "deep": "Estimate orders of magnitude before drawing architecture: requests per day to average QPS, peak multiplier, bytes per record, retention, and replica overhead. State assumptions and distinguish read from write volume. Error budgets quantify allowed unreliability and inform change policy. Use measured percentiles and realistic headroom; averages hide peaks and correlated failures.", "examples": ["8.64 million requests/day is 100 average QPS; a 5× peak assumption gives 500 peak QPS.", "One million 1 KB records/day requires about 1 GB/day raw, before indexes, metadata, replicas, and backups."], "nodes": ["Requirements", "Traffic estimate", "Storage estimate", "SLO budget"], "steps": ["Define user-visible operations and acceptable failure/latency conditions.", "Convert daily volume to average and plausible peak rates.", "Multiply record size by volume and retention, adding overhead assumptions.", "Choose a measurable objective and reserve headroom for peaks and failures."], "pitfall": "Capacity estimates are assumptions to validate, not precise promises; include replication, indexing, and peak behavior.", "minutes": 11, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=SLIs%2C%20SLOs%2C%20SLAs%20%26%20capacity%20estimates%20explained%20computer%20science", "takeaway": "Capacity estimates are assumptions to validate, not precise promises; include replication, indexing, and peak behavior."}, {"id": "consistent-hashing-virtual-nodes", "module": "systems", "title": "Consistent hashing & virtual nodes", "level": "Intermediate", "concept": "Naive hash(key) modulo N changes many assignments when N changes. Consistent hashing places nodes and keys on a ring, assigning each key to the next eligible node clockwise. Adding a node mostly moves keys in its newly owned ranges. Virtual nodes give each physical machine multiple positions to improve distribution and support weighted capacity.", "deep": "Routing stability does not move stored data for you. Membership changes require copying, replica repair, ownership rules, and handling stale routing. Uneven key popularity can still create hotspots even with even key counts. Rendezvous hashing is another assignment approach. Measure movement, balance, and request load rather than treating a diagram of a ring as a complete storage protocol.", "examples": ["If A, B, C occupy the ring, adding D between B and C moves only keys in the newly claimed interval in the simplified model.", "A larger server gets more virtual nodes so it owns a larger fraction of the key space."], "nodes": ["Hash key", "Place on ring", "Walk clockwise", "Select owner"], "steps": ["Compute a stable hash of the key.", "Locate its position in the same hash space as virtual nodes.", "Find the first virtual node clockwise, wrapping if needed.", "Map that virtual node to a physical owner; migration must make the data available there."], "pitfall": "Consistent hashing reduces remapping, not every kind of hotspot or migration failure.", "minutes": 11, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Consistent%20hashing%20%26%20virtual%20nodes%20explained%20computer%20science", "takeaway": "Consistent hashing reduces remapping, not every kind of hotspot or migration failure."}, {"id": "rate-limiting-buckets-windows", "module": "systems", "title": "Rate limiting: buckets & windows", "level": "Foundation", "concept": "A rate limiter decides whether to admit an operation according to a budget. Fixed windows count within calendar buckets and can allow a burst at the boundary. Sliding logs track exact recent timestamps at higher memory cost; sliding counters approximate rolling usage. A token bucket refills tokens up to a capacity, allowing bounded bursts; a leaky-bucket model drains at a controlled rate.", "deep": "Choose the identity being limited, the unit of cost, and the scope: user, tenant, IP, endpoint, or global dependency. Distributed admission must update state atomically, often through a Redis script or equivalent primitive. Return meaningful 429 responses and retry hints. Define behavior when the limiter store is unavailable. Rate limits complement concurrency limits, which bound in-flight work rather than arrivals per time.", "examples": ["A capacity-five token bucket allows five immediate requests, then admits more only as tokens refill.", "A fixed 100/minute limit can allow 100 at 12:00:59 and 100 at 12:01:00; a rolling window addresses that boundary burst."], "nodes": ["Request", "Refill tokens", "Check budget", "Admit or 429"], "steps": ["Identify the caller and the operation cost.", "Add elapsed-time refill while clamping to capacity.", "Atomically compare available tokens with required cost.", "Consume tokens and admit, or reject with a calculated retry time."], "pitfall": "A local limiter in each of ten replicas may allow ten times the intended global limit.", "minutes": 11, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Rate%20limiting%3A%20buckets%20%26%20windows%20explained%20computer%20science", "takeaway": "A local limiter in each of ten replicas may allow ten times the intended global limit."}, {"id": "unique-ids-uuids-snowflake-tickets", "module": "systems", "title": "Unique IDs: UUIDs, Snowflake & tickets", "level": "Intermediate", "concept": "Globally unique identifiers avoid collisions across independent writers. UUID variants offer different ordering and information properties; random UUIDs are decentralized but can hurt locality in some indexes. Time-ordered UUID variants improve ordering characteristics while still requiring correct generation. Snowflake-style IDs combine time, worker identity, and a per-time-unit sequence.", "deep": "A Snowflake implementation must handle clock rollback, worker-ID collisions, and sequence exhaustion. Ticket servers centralize allocation and need availability and scaling plans. Identifier uniqueness is separate from authorization and business deduplication: two unique payment IDs can still represent an accidental duplicate charge. Exposing time-ordered or sequential IDs may reveal volume or timing information.", "examples": ["Two independent application replicas generate UUIDs without asking a single central counter for every write.", "A Snowflake generator reserves worker bits so two machines can generate IDs in the same millisecond without overlap."], "nodes": ["Current time", "Worker ID", "Sequence", "Combined ID"], "steps": ["Read a permitted logical/physical timestamp and detect rollback.", "Add the unique worker allocation for this generator.", "Increment the sequence within that time unit and handle exhaustion.", "Combine fields into an ID and preserve the chosen ordering/uniqueness contract."], "pitfall": "Uniqueness is not secrecy, and a unique ID does not make a repeated business operation idempotent.", "minutes": 10, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Unique%20IDs%3A%20UUIDs%2C%20Snowflake%20%26%20tickets%20explained%20computer%20science", "takeaway": "Uniqueness is not secrecy, and a unique ID does not make a repeated business operation idempotent."}, {"id": "bloom-filters-hyperloglog-search-object-storage", "module": "systems", "title": "Bloom filters, HyperLogLog, search & object storage", "level": "Intermediate", "concept": "Probabilistic structures trade exactness for memory. A Bloom filter can reject definitely absent keys with possible false positives; HyperLogLog estimates distinct counts without retaining every ID. These answer different questions. Object storage keeps blobs by key with metadata and service-specific consistency guarantees. Search engines such as Elasticsearch build inverted indexes and offer text analysis and ranked retrieval.", "deep": "Use the right storage for the access path: transaction tables for authoritative relational rules, object storage for large immutable payloads, search projections for discovery. Maintain lineage and versioning so derived indexes can be rebuilt. Approximate distinct counts must be labeled estimates, and search index refresh can lag the database. A file’s object key should not substitute for an authorization check.", "examples": ["HyperLogLog estimates unique visitors for a day while using far less memory than storing every visitor ID.", "Upload a video to object storage, store metadata in SQL, and index title tokens in search."], "nodes": ["Authoritative write", "Outbox event", "Derived search index", "Search response"], "steps": ["Commit metadata in the authoritative database.", "Publish a reliable change event through the outbox.", "Update the searchable projection asynchronously and record its version.", "Return search results with known freshness limitations and enforce access controls."], "pitfall": "Approximate counts and eventually refreshed indexes are useful only when their uncertainty and freshness are acceptable.", "minutes": 11, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Bloom%20filters%2C%20HyperLogLog%2C%20search%20%26%20object%20storage%20explained%20computer%20science", "takeaway": "Approximate counts and eventually refreshed indexes are useful only when their uncertainty and freshness are acceptable."}, {"id": "consensus-clocks-gossip-pacelc", "module": "systems", "title": "Consensus, clocks, gossip & PACELC", "level": "Advanced", "concept": "Consensus protocols such as Raft and Paxos coordinate agreement despite selected failures under stated assumptions. Raft uses terms, leader election, and replicated logs, with majorities forming a safety boundary. Gossip spreads membership or state through repeated peer exchanges without automatically giving linearizable agreement. Vector clocks track causal relationships and can reveal concurrent updates rather than forcing a total order.", "deep": "Physical clocks drift and can jump; use monotonic time for durations and avoid assuming timestamps establish causality across machines. PACELC adds that even outside partitions, systems may trade latency against consistency. Consensus guarantees safety under its failure assumptions, while liveness depends on communication and timing conditions. Read the protocol carefully before using a lease or a majority count as a substitute for a proven algorithm.", "examples": ["In a five-voter Raft cluster, a connected majority of three can elect a leader under the protocol while a minority cannot safely commit alone.", "Two disconnected writers may produce incomparable vector clocks, signaling concurrent edits requiring a conflict policy."], "nodes": ["Leader proposal", "Replicate log", "Majority acknowledgement", "Commit"], "steps": ["The current-term leader proposes a log entry.", "It sends the entry to followers under the replication protocol.", "A qualifying majority stores the entry, subject to Raft’s term/commit rules.", "Mark the entry committed and apply it in order; lagging replicas catch up later."], "pitfall": "A majority alone is not a complete consensus protocol; terms, log matching, membership, and failure assumptions matter.", "minutes": 11, "references": [["Raft paper & resources", "https://raft.github.io/"], ["Redis rate limiter guide", "https://redis.io/learn/develop/java/spring/rate-limiting/fixed-window"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Consensus%2C%20clocks%2C%20gossip%20%26%20PACELC%20explained%20computer%20science", "takeaway": "A majority alone is not a complete consensus protocol; terms, log matching, membership, and failure assumptions matter."}, {"id": "url-shortener", "module": "designs", "title": "URL shortener", "level": "Design exercise", "concept": "Accept a long URL, issue a compact code, and redirect reads with low latency. Define expiry, custom aliases, abuse controls, analytics freshness, and whether links are public. Estimate redirects separately from creates because reads usually dominate.", "deep": "Store code→destination behind a unique constraint, generate collision-safe IDs, and cache hot mappings. Use redirect status and cache policy deliberately: long-lived permanent redirects can make destination changes difficult. Publish click analytics asynchronously so collection does not delay navigation.", "examples": ["A six-character code maps to a product page and returns a redirect.", "A celebrity shares a link; edge/application caching absorbs the burst while analytics queues grow within limits."], "nodes": ["Create link", "Unique mapping", "Cached redirect", "Async click event"], "steps": ["Validate the destination and create a collision-safe code.", "Persist the mapping and expiry atomically.", "Resolve the code through cache then storage and return an allowed redirect.", "Emit a click event without blocking the redirect on reporting."], "pitfall": "Guard against malicious destinations and never allow stale cache entries to ignore deletion or expiry indefinitely.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=URL%20shortener%20explained%20computer%20science", "takeaway": "Guard against malicious destinations and never allow stale cache entries to ignore deletion or expiry indefinitely."}, {"id": "rate-limiter-service", "module": "designs", "title": "Rate limiter service", "level": "Design exercise", "concept": "Define the protected identity, allowed burst, steady rate, and whether decisions must be globally strict. Estimate check QPS because every protected operation can add a limiter call. Choose token buckets or rolling windows from product behavior.", "deep": "Partition limiter state by key and update counters atomically. Cache policy configuration locally while preserving versioning. Decide fail-open or fail-closed per endpoint when the backing store is unavailable; a login endpoint and a public read API may need different policies.", "examples": ["Limit a tenant to 100 writes/minute with a burst of 20.", "A shared NAT IP should not accidentally force every authenticated user into one account-level budget."], "nodes": ["Caller identity", "Policy lookup", "Atomic budget check", "Admit/reject"], "steps": ["Authenticate the caller and derive the scoped limit key.", "Load the applicable versioned policy.", "Refill/check/consume in one atomic operation.", "Admit or return 429 with safe retry guidance."], "pitfall": "A global strict limiter adds latency and availability dependencies; make that trade-off explicit.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Rate%20limiter%20service%20explained%20computer%20science", "takeaway": "A global strict limiter adds latency and availability dependencies; make that trade-off explicit."}, {"id": "pastebin", "module": "designs", "title": "Pastebin", "level": "Design exercise", "concept": "Support creating a text paste and fetching it by ID, with optional expiry and access restrictions. Separate public discovery from possession of an unguessable URL. Bound paste size and choose whether content is immutable.", "deep": "Store metadata in a database and larger text in object storage if useful. Cache public immutable pastes, track expiry, and enforce authorization before serving private content. Background deletion must account for object versions, replicas, and caches.", "examples": ["A public paste is shared with a random ID and expires after one day.", "A private incident note requires an authenticated team permission check on every fetch."], "nodes": ["Submit paste", "Persist metadata", "Store content", "Fetch by ID"], "steps": ["Validate size and requested visibility.", "Allocate an ID and record ownership/expiry.", "Persist content with a recoverable workflow if metadata and blobs are separate.", "Fetch only after checking visibility and expiry."], "pitfall": "An unguessable URL is a bearer capability, not equivalent to full account-based access control.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Pastebin%20explained%20computer%20science", "takeaway": "An unguessable URL is a bearer capability, not equivalent to full account-based access control."}, {"id": "key-value-store", "module": "designs", "title": "Key-value store", "level": "Design exercise", "concept": "Define get, put, delete, TTL, value size, and consistency before picking storage. In-memory local stores differ dramatically from durable distributed stores. Estimate read/write rates and working-set size.", "deep": "For durability, coordinate a write-ahead log, in-memory state, snapshots, and recovery ordering. Shard by key, replicate with a defined consistency model, and specify behavior during partitions. Checksums and compaction need operational testing.", "examples": ["A local store keeps counters in memory with bounded expiry.", "A durable service replays its log after a restart to restore committed values."], "nodes": ["PUT key", "Append log", "Update state", "GET key"], "steps": ["Validate key/value limits and an optional conditional version.", "Record the update according to the durability contract.", "Apply it to the in-memory index after the required log boundary.", "Return the current value or a defined missing/expired result."], "pitfall": "Acknowledging before durable storage changes the failure guarantee; do not promise persistence without the corresponding protocol.", "minutes": 8, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Key-value%20store%20explained%20computer%20science", "takeaway": "Acknowledging before durable storage changes the failure guarantee; do not promise persistence without the corresponding protocol."}, {"id": "notification-system", "module": "designs", "title": "Notification system", "level": "Design exercise", "concept": "Handle email, push, and SMS through one intent API while preserving preferences and consent. Separate transactional alerts from campaigns, priorities, delivery deadlines, and provider cost. Accepted, delivered, and read are different states.", "deep": "Use durable events, recipient/channel preferences, templates, per-channel queues, and provider adapters. Retry with provider-aware policies, deduplicate notification intents, and record delivery receipts. Fallback channels must honor consent and avoid surprising duplicate sends.", "examples": ["A password-reset email takes priority over a newsletter.", "A failed push may trigger permitted email fallback while preserving the same notification intent."], "nodes": ["Notification intent", "Preferences", "Channel queue", "Provider receipt"], "steps": ["Record a stable intent and allowed channels.", "Check consent, quiet hours, and destination validity.", "Enqueue a channel-specific task with priority and expiry.", "Send idempotently where supported and reconcile delivery callbacks."], "pitfall": "A provider accepting a message does not prove the user received or read it.", "minutes": 8, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Notification%20system%20explained%20computer%20science", "takeaway": "A provider accepting a message does not prove the user received or read it."}, {"id": "chat-application", "module": "designs", "title": "Chat application", "level": "Design exercise", "concept": "Support sending, history, delivery status, reconnect, and multi-device access. Define ordering per conversation, offline behavior, and group sizes. Presence is usually approximate, while accepted messages need durable history.", "deep": "Use WebSockets for live delivery, durable message storage, per-conversation sequence or ordering metadata, and shared routing/pub-sub across connection servers. Reconnect by fetching missed history from a cursor. Slow consumers need bounded queues and resync rather than unlimited buffering.", "examples": ["An offline user receives history after reconnecting from their last stored sequence.", "Two devices for one user each receive the same message while the server stores it once."], "nodes": ["Sender socket", "Persist message", "Route fan-out", "Recipient ack"], "steps": ["Authenticate the sender and authorize conversation membership.", "Assign an ID/order and durably store the message before accepted acknowledgement.", "Publish to eligible connected devices and queue offline notifications if appropriate.", "Track delivery/read receipts separately from server acceptance."], "pitfall": "WebSocket delivery alone does not provide durable history, end-to-end encryption, or exactly-once display.", "minutes": 8, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Chat%20application%20explained%20computer%20science", "takeaway": "WebSocket delivery alone does not provide durable history, end-to-end encryption, or exactly-once display."}, {"id": "news-feed", "module": "designs", "title": "News feed", "level": "Design exercise", "concept": "Design post creation and a paginated personalized feed. Clarify chronological versus ranked ordering, follow graph, visibility, and freshness. Separate the author’s durable post from derived feed entries.", "deep": "Fan-out-on-write precomputes feeds for fast reads but makes celebrity writes expensive. Fan-out-on-read combines posts at read time but increases read work. A hybrid precomputes normal authors and merges high-fan-out authors later. Cursor ordering and content deletion must remain consistent with access policy.", "examples": ["A user following 100 friends reads a precomputed feed quickly.", "A celebrity’s post is merged at read time instead of writing millions of feed rows immediately."], "nodes": ["New post", "Follower policy", "Fan-out/merge", "Paged feed"], "steps": ["Store the post with its visibility rules.", "Choose push or pull distribution based on follower count and workload.", "Build or merge candidate feed entries and rank under a latency budget.", "Return a deterministic page and recheck access/deletion rules."], "pitfall": "Deleting the original post must also stop exposure through stale feed and cache projections.", "minutes": 8, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=News%20feed%20explained%20computer%20science", "takeaway": "Deleting the original post must also stop exposure through stale feed and cache projections."}, {"id": "instagram-style-media", "module": "designs", "title": "Instagram-style media", "level": "Design exercise", "concept": "Support uploads, processing, posts, follows, feed, and media delivery. Estimate bytes and bandwidth separately from metadata QPS; images and videos dominate storage and egress. Define privacy and processing states.", "deep": "Use signed upload URLs to object storage, metadata in a transactional store, asynchronous thumbnail/transcode workers, and CDN delivery. Publish only validated media states. Feed, likes, and comments have different scaling and consistency requirements; counts can be derived while permissions remain authoritative.", "examples": ["A phone uploads directly to object storage and receives a processing status.", "A worker creates mobile-size thumbnails so feed clients avoid downloading full-resolution originals."], "nodes": ["Signed upload", "Object storage", "Media processing", "CDN delivery"], "steps": ["Authorize an upload and allocate scoped temporary credentials/URL.", "Store the media and confirm it belongs to the expected upload.", "Validate and generate variants asynchronously with idempotent tasks.", "Publish the ready post and serve allowed variants through controlled delivery."], "pitfall": "A public CDN URL can outlive a privacy change unless access and cache behavior are designed for revocation.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Instagram-style%20media%20explained%20computer%20science", "takeaway": "A public CDN URL can outlive a privacy change unless access and cache behavior are designed for revocation."}, {"id": "youtube-netflix-style-streaming", "module": "designs", "title": "YouTube / Netflix-style streaming", "level": "Design exercise", "concept": "Separate upload/ingestion, transcoding, catalog, playback authorization, and video delivery. Adaptive bitrate streaming splits media into segments at multiple quality levels so clients adapt to available bandwidth. Estimate egress as well as storage.", "deep": "Queue transcoding with bounded CPU/GPU workers, place immutable segments in object storage, and distribute through CDNs. The playback API returns authorized manifests and metadata. Regional availability, DRM where required, recommendations, and viewing history are separate concerns with distinct consistency needs.", "examples": ["A slow connection switches from a high-bitrate representation to a lower one without restarting playback.", "A popular episode is served from CDN cache while origin storage handles misses."], "nodes": ["Upload master", "Transcode variants", "Publish manifest", "Play CDN segments"], "steps": ["Ingest and validate the original video.", "Produce aligned segments at supported quality levels.", "Publish a manifest only when required assets are ready.", "The player selects quality and downloads authorized segments through a CDN."], "pitfall": "Adaptive bitrate is not simply compressing one large file; manifest, segmentation, alignment, and buffering behavior matter.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=YouTube%20/%20Netflix-style%20streaming%20explained%20computer%20science", "takeaway": "Adaptive bitrate is not simply compressing one large file; manifest, segmentation, alignment, and buffering behavior matter."}, {"id": "ride-hailing-uber", "module": "designs", "title": "Ride hailing / Uber", "level": "Design exercise", "concept": "Support rider requests, nearby-driver discovery, matching, trip state, and payments. Locations update frequently; availability, assignment, and trip transitions require stronger control than approximate map display. Define region and latency targets.", "deep": "Use a spatial index for candidates, then match based on ETA and policy. An atomic assignment or compare-and-set prevents two riders claiming the same driver. Stream locations with bounded freshness and keep an auditable trip state machine. Reconcile payments asynchronously with stable operation identities.", "examples": ["A rider finds drivers in adjacent geo cells rather than scanning every active driver worldwide.", "Two riders choose the same driver; only one assignment version succeeds and the other retries matching."], "nodes": ["Rider request", "Nearby lookup", "Atomic match", "Trip lifecycle"], "steps": ["Create a request with pickup, eligibility, and timeout.", "Search fresh nearby driver candidates and compute a practical ranking.", "Reserve one candidate with an atomic availability transition.", "Track accepted, arrived, started, and completed states with authorized transitions."], "pitfall": "Geographic proximity is not the same as shortest travel time; routing and stale location data affect matching.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Ride%20hailing%20/%20Uber%20explained%20computer%20science", "takeaway": "Geographic proximity is not the same as shortest travel time; routing and stale location data affect matching."}, {"id": "dropbox-drive-style-files", "module": "designs", "title": "Dropbox / Drive-style files", "level": "Design exercise", "concept": "Support upload, download, folders, versions, sharing, and synchronization. Large files need chunked or resumable transfer; metadata and file content follow different access patterns. Define conflict behavior for offline edits.", "deep": "Keep authoritative metadata and permissions in a database, chunks/objects in blob storage, and change cursors for sync. Content hashes can support dedupe, but privacy and tenant isolation matter. Version IDs prevent overwriting concurrent edits silently. Deletion, retention, quotas, and garbage collection must account for shared or referenced chunks.", "examples": ["An interrupted upload resumes missing chunks rather than restarting a multi-gigabyte file.", "Two offline edits produce a conflict copy or explicit merge rather than silently discarding one version."], "nodes": ["Chunk upload", "Hash/verify", "Commit version", "Sync cursor"], "steps": ["Upload bounded chunks using scoped authorization.", "Validate sizes and hashes before accepting them.", "Atomically publish a new metadata version referencing complete content.", "Expose a change cursor so other devices fetch the new version."], "pitfall": "File content deduplication must not leak whether another user possesses sensitive content.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Dropbox%20/%20Drive-style%20files%20explained%20computer%20science", "takeaway": "File content deduplication must not leak whether another user possesses sensitive content."}, {"id": "web-crawler", "module": "designs", "title": "Web crawler", "level": "Design exercise", "concept": "Design URL discovery, a frontier, polite fetching, content parsing, and deduplicated storage. Bound the crawl by allowed scope, budget, and freshness. A crawler schedules a graph traversal over an unstable, potentially infinite web.", "deep": "Partition the frontier by domain so per-host delays are enforceable. Normalize URLs cautiously, check robots guidance and terms, avoid traps, record fetch outcomes, and checkpoint progress. Separate fetch workers from parsing and indexing. Respect access restrictions and treat 429/403 as policy signals rather than challenges to bypass.", "examples": ["A domain queue schedules one request per allowed interval while other domains progress independently.", "A content hash identifies unchanged pages and avoids reindexing duplicate text."], "nodes": ["URL frontier", "Domain policy", "Fetch + parse", "Dedup + new URLs"], "steps": ["Choose the next allowed URL from a bounded frontier.", "Check scope, robots guidance, rate budget, and prior failures.", "Fetch with timeouts and parse safely without following unbounded traps.", "Store content/checkpoints and enqueue newly discovered permitted URLs."], "pitfall": "URL normalization can merge distinct resources incorrectly; define rules carefully and retain original URLs.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Web%20crawler%20explained%20computer%20science", "takeaway": "URL normalization can merge distinct resources incorrectly; define rules carefully and retain original URLs."}, {"id": "typeahead-autocomplete", "module": "designs", "title": "Typeahead / autocomplete", "level": "Design exercise", "concept": "Return relevant suggestions for a prefix under a tight latency budget. Define language, normalization, ranking, personalization, and freshness. Prefix lookup and ranking are separate problems; returning every matching string is not useful.", "deep": "Use a trie, radix tree, or a search index with prefix-oriented structures, then keep bounded top candidates. Precompute popular prefixes when appropriate, cache hot queries, and version snapshots. Debounce browser requests and ignore stale responses arriving after newer input. Monitor zero-result queries and ranking quality.", "examples": ["Typing ca returns camera, cake, and camping ranked by a defined popularity signal.", "The response for c arrives after ca; the UI ignores it using a request sequence number."], "nodes": ["Prefix input", "Normalize", "Candidate lookup", "Rank top-k"], "steps": ["Normalize the current input consistently with indexed terms.", "Apply language/case rules and validate minimum prefix length.", "Locate a prefix region without scanning the whole vocabulary.", "Return a bounded ranked set and label the response with its query context."], "pitfall": "Fast prefix retrieval does not guarantee useful ranking or correct multilingual behavior.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Typeahead%20/%20autocomplete%20explained%20computer%20science", "takeaway": "Fast prefix retrieval does not guarantee useful ranking or correct multilingual behavior."}, {"id": "ticket-booking", "module": "designs", "title": "Ticket booking", "level": "Design exercise", "concept": "Model shows, seats, temporary holds, orders, and payments. The critical invariant is that one seat cannot be sold to two buyers. Search pages may be slightly stale, while the final reservation must use authoritative concurrency control.", "deep": "Use transactional conditional updates or unique constraints for seat ownership, with explicit hold expiry and payment reconciliation. Distinguish available, held, sold, and released states. A queue may smooth flash-sale traffic, but the seat database still enforces correctness. A timed-out payment needs reconciliation before releasing a seat or retrying a charge.", "examples": ["Two customers attempt seat A1; only one valid available→held update succeeds.", "An unpaid hold expires after its deadline and becomes available through a guarded state transition."], "nodes": ["Choose seat", "Atomic hold", "Payment result", "Confirm or release"], "steps": ["Read availability as an advisory view.", "Create a hold only if the authoritative state and expiry allow it.", "Charge using a stable idempotency key and reconcile unknown outcomes.", "Confirm the sale or release the hold through valid versioned transitions."], "pitfall": "A Redis lock by itself is not sufficient proof that a seat was never sold twice; preserve the database invariant.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Ticket%20booking%20explained%20computer%20science", "takeaway": "A Redis lock by itself is not sufficient proof that a seat was never sold twice; preserve the database invariant."}, {"id": "payment-system-wallet", "module": "designs", "title": "Payment system / wallet", "level": "Design exercise", "concept": "Start with correctness: money units, ledger accounts, idempotency, authorization, settlement, refunds, and reconciliation. Distinguish internal balance transfers from external payment-provider operations. Immutable audit evidence matters more than cosmetic status labels.", "deep": "Use decimal or integer minor units under explicit currency rules, balanced ledger postings, atomic local transfers, and unique operation references. External charges need a durable state machine, provider idempotency, webhook dedupe, and reconciliation jobs. Never infer failure solely from a timeout or success solely from a browser redirect.", "examples": ["Transfer 500 minor units from A to B in one local transaction with balanced postings.", "A payment response is lost; query/reconcile the same provider operation before deciding whether to retry."], "nodes": ["Payment intent", "Idempotency check", "Ledger/provider step", "Reconciliation"], "steps": ["Create a durable intent with amount, currency, and business reference.", "Atomically prevent duplicate logical operations.", "Apply local postings transactionally or call the provider with a stable key.", "Reconcile asynchronous callbacks and unknown outcomes into an auditable terminal state."], "pitfall": "Distributed money movement cannot be made atomic by wrapping only your own database calls in a transaction.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Payment%20system%20/%20wallet%20explained%20computer%20science", "takeaway": "Distributed money movement cannot be made atomic by wrapping only your own database calls in a transaction."}, {"id": "distributed-cache-message-queue", "module": "designs", "title": "Distributed cache & message queue", "level": "Design exercise", "concept": "These are two related infrastructure exercises with different guarantees. A cache prioritizes reusable low-latency reads and can tolerate selected misses or stale entries. A queue prioritizes task retention, acknowledgement, delivery, and recovery. Define contracts separately before sharing infrastructure.", "deep": "For a cache, cover sharding, eviction, TTL, replication, and stampede protection. For a queue, cover partitioning, visibility/leases, acknowledgements, retries, dead letters, and retention. Both need bounded memory, observability, and failure recovery, but eviction of a cache entry is routine while silent eviction of an accepted task may violate the queue contract.", "examples": ["Cache: losing a product entry triggers a database reload.", "Queue: a worker crash causes an unacknowledged task to become eligible again."], "nodes": ["Task accepted", "Durable broker", "Leased delivery", "Ack/redelivery"], "steps": ["Validate and durably accept the task under the queue contract.", "Retain it until the defined acknowledgement or retention boundary.", "Deliver it to a worker with a visibility/ownership mechanism.", "On success acknowledge; on worker loss permit safe redelivery."], "pitfall": "Do not configure accepted business tasks to disappear under an ordinary cache eviction policy.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Distributed%20cache%20%26%20message%20queue%20explained%20computer%20science", "takeaway": "Do not configure accepted business tasks to disappear under an ordinary cache eviction policy."}, {"id": "collaborative-documents-google-docs", "module": "designs", "title": "Collaborative documents / Google Docs", "level": "Design exercise", "concept": "Support concurrent edits, reconnect, shared presence, permissions, and durable revision history. Text positions change under concurrent edits, so naive last-write-wins replacement loses work. Define the operation model and offline behavior before choosing algorithms.", "deep": "Operational transformation and CRDTs are families of approaches for reconciling concurrent operations under specific assumptions. A collaboration server routes operations, persists history/snapshots, and validates permissions. Clients need deduplication, causal/version metadata, and recovery from missing history. Presence can be ephemeral while accepted edits need stronger durability.", "examples": ["Two users insert text at the same position; the merge protocol deterministically preserves intended content under its rules.", "An offline editor reconnects, submits queued operations, and merges against newer shared state."], "nodes": ["Local edit", "Operation metadata", "Merge protocol", "Persist & broadcast"], "steps": ["Turn a local change into an identified operation.", "Attach the context required by the chosen OT/CRDT algorithm.", "Transform or merge with concurrent accepted operations according to its formal rules.", "Persist, broadcast, acknowledge, and periodically snapshot for bounded recovery."], "pitfall": "WebSockets broadcast edits but do not solve concurrent text merging by themselves.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Collaborative%20documents%20/%20Google%20Docs%20explained%20computer%20science", "takeaway": "WebSockets broadcast edits but do not solve concurrent text merging by themselves."}, {"id": "llm-vector-search-pipeline", "module": "designs", "title": "LLM + vector search pipeline", "level": "Design exercise", "concept": "Design ingestion, parsing, embedding, vector indexing, retrieval, generation, and progress delivery as separate stages. Define document permissions, index freshness, response latency, cost budgets, and cancellation. Heavy model work should not occupy an API event loop.", "deep": "Use durable jobs, separate ingestion/search/generation worker budgets, versioned model/index caches, and SSE or polling for progress. Load expensive resources once per worker where safe and batch appropriately. Retrieval must enforce document-level access before model context is built. Trace queue wait, retrieval, inference, and streaming latency separately.", "examples": ["A document upload returns a job ID while parsing and embedding run asynchronously.", "A repeated query reuses a model/index-versioned retrieval result without leaking another tenant’s documents."], "nodes": ["Ingest documents", "Embed + index", "Retrieve context", "Generate + stream"], "steps": ["Validate ownership and record ingestion lineage/checkpoints.", "Workers compute versioned embeddings and publish a consistent index view.", "Retrieve permitted candidates and build bounded context with references.", "Generate under cost/time limits and stream durable stage status to the client."], "pitfall": "Caching only by query text can mix tenants, models, or index versions and return stale or unauthorized context.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=LLM%20%2B%20vector%20search%20pipeline%20explained%20computer%20science", "takeaway": "Caching only by query text can mix tenants, models, or index versions and return stale or unauthorized context."}, {"id": "erp-order-to-cash-saga", "module": "designs", "title": "ERP order-to-cash saga", "level": "Design exercise", "concept": "Model order approval, inventory reservation, invoice creation, collection, and ledger posting with explicit ownership. Keep local accounting invariants transactional and make every cross-service step recoverable. Define which states can be revised and which need reversal entries.", "deep": "An orchestrator records progress and calls idempotent steps, using outbox events and deduplicated callbacks. Compensation may release a reservation or reverse a provisional posting, while settled financial effects require approved correction workflows. Add reconciliation for unknown outcomes and an operator queue for recovery that cannot be completed automatically.", "examples": ["A failed credit check releases inventory before the order reaches fulfillment.", "A duplicate collection callback has the same operation ID and cannot create a second ledger credit."], "nodes": ["Approve order", "Reserve + invoice", "Collect payment", "Post & reconcile"], "steps": ["Validate the order lifecycle and record the workflow intent.", "Reserve stock and create invoice state through guarded local transactions.", "Collect with a stable payment identity and wait/reconcile unknown results.", "Post balanced entries once and complete only after required confirmations."], "pitfall": "Compensation must preserve audit history; silently deleting financial records is not a valid recovery policy.", "minutes": 9, "references": [["AWS architecture center", "https://aws.amazon.com/architecture/"], ["Google SRE book", "https://sre.google/sre-book/table-of-contents/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=ERP%20order-to-cash%20saga%20explained%20computer%20science", "takeaway": "Compensation must preserve audit history; silently deleting financial records is not a valid recovery policy."}, {"id": "parking-lot-library-booking-models", "module": "lld", "title": "Parking lot, library & booking models", "level": "Foundation", "concept": "Low-level design starts with entities, invariants, and use cases. A parking lot has spaces, vehicles, tickets, and allocation rules. A library has titles, physical copies, members, loans, and reservations. Booking systems distinguish a searchable offering from a reservable unit and a confirmed purchase. Separate identity and lifecycle instead of placing every rule in one manager class.", "deep": "Define commands and valid transitions, then assign each invariant an owner. Use interfaces for genuinely variable policies such as pricing or allocation. Add concurrency checks where two commands compete for one unit. Test the domain model without a UI or production database. Expand only after the basic model handles invalid input, duplicates, and cancellation.", "examples": ["A library title can have five copies; lending one copy does not make the entire title unavailable.", "Parking allocation chooses a compatible free space and creates exactly one active ticket for it."], "nodes": ["Allocation request", "Policy chooses unit", "Guard availability", "Create reservation"], "steps": ["Validate the actor and requested unit type.", "Use an allocation strategy to choose an eligible candidate.", "Atomically claim the candidate’s current version/state.", "Create the ticket/loan/booking and preserve the one-active-owner invariant."], "pitfall": "Class diagrams without invariants and transition rules do not establish a correct design.", "minutes": 11, "references": [["Martin Fowler • patterns", "https://martinfowler.com/tags/design.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Parking%20lot%2C%20library%20%26%20booking%20models%20explained%20computer%20science", "takeaway": "Class diagrams without invariants and transition rules do not establish a correct design."}, {"id": "elevator-atm-vending-state-machines", "module": "lld", "title": "Elevator, ATM & vending state machines", "level": "Foundation", "concept": "State machines make permitted transitions explicit. A vending machine distinguishes idle, payment pending, dispensing, and recovery. An ATM distinguishes authenticated session, selected operation, authorized withdrawal, and cash-dispense outcome. An elevator has motion, door, floor, and request state, with safety interlocks. Model failures and cancellation as first-class transitions.", "deep": "Separate input events, transition logic, and external device effects. A state transition should not assume a device succeeded merely because a command was sent. Record uncertain outcomes for reconciliation, and avoid inconsistent combinations such as moving while the door is open. Strategies can choose scheduling or pricing while the state machine protects safety and lifecycle.", "examples": ["A vending machine accepts payment, checks stock, dispenses, then records completion or a controlled refund path.", "An elevator closes and verifies doors before moving; an obstruction returns it to a safe door state."], "nodes": ["Idle", "Payment accepted", "Dispensing", "Complete/recover"], "steps": ["Await a valid selection and verify inventory.", "Record authorized payment and the selected item.", "Issue a dispense command and wait for device confirmation.", "Complete only after confirmation; otherwise enter a recoverable failure state."], "pitfall": "External device actions are not rolled back by ordinary in-memory state changes.", "minutes": 10, "references": [["Martin Fowler • patterns", "https://martinfowler.com/tags/design.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Elevator%2C%20ATM%20%26%20vending%20state%20machines%20explained%20computer%20science", "takeaway": "External device actions are not rolled back by ordinary in-memory state changes."}, {"id": "games-tic-tac-toe-chess-snake-ladder", "module": "lld", "title": "Games: tic-tac-toe, chess, snake & ladder", "level": "Foundation", "concept": "A turn-based game separates board state, legal actions, turn order, outcome rules, and presentation. Tic-tac-toe checks lines; chess has piece movement, king safety, castling, en passant, promotion, and draw rules; snake and ladder uses dice and board transitions. A reusable design should not erase the important differences between games.", "deep": "Represent a move as a command against a known state/version. Validate before applying, keep enough history for undo or replay where required, and compute the next state deterministically from the rules. Multiplayer transport and timing sit outside the core rule engine. Strategy or policy interfaces can vary players and dice sources without turning every square into a separate abstraction.", "examples": ["Tic-tac-toe rejects playing on an occupied square and checks for a win before changing turns.", "Chess move validation must reject a move that leaves the moving side’s king in check, even if the piece movement shape is valid."], "nodes": ["Player move", "Validate rules", "Apply state", "Check outcome"], "steps": ["Accept an action tied to the current game version and player.", "Verify turn, coordinates, and game-specific legality.", "Create or update the next board state atomically.", "Evaluate win/draw/continuation and select the next player."], "pitfall": "A shared board representation does not mean all games share the same legality and outcome rules.", "minutes": 10, "references": [["Martin Fowler • patterns", "https://martinfowler.com/tags/design.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Games%3A%20tic-tac-toe%2C%20chess%2C%20snake%20%26%20ladder%20explained%20computer%20science", "takeaway": "A shared board representation does not mean all games share the same legality and outcome rules."}, {"id": "splitwise-cab-booking-concurrency-safe-utilities", "module": "lld", "title": "Splitwise, cab booking & concurrency-safe utilities", "level": "Intermediate", "concept": "Splitwise models expenses, participants, shares, and settlement rather than only a mutable balance per user. Cab booking models drivers, ride requests, assignment, and trip states. Utility exercises such as LRU cache, logger, and rate limiter focus on clear interfaces plus bounded memory and concurrency behavior. Pick one use case and state its invariants before writing classes.", "deep": "Expense shares must sum to the expense in the currency’s chosen precision, with a deliberate remainder policy. Booking must guard assignment against races. An LRU combines map and list with one consistent synchronization strategy. A logger needs structured records, bounded buffering, and failure policy. Apply SOLID and patterns only where the design has real substitution needs.", "examples": ["Split a 100-unit expense among three people as 34,33,33 under a documented rounding rule.", "Two concurrent LRU gets update one list safely; unsynchronized pointer changes can corrupt recency order."], "nodes": ["Expense command", "Validate shares", "Persist entries", "Derive balances"], "steps": ["Identify payer, participants, amount, currency, and operation ID.", "Check shares sum exactly to the amount under the rounding rule.", "Record the expense and owed entries atomically and only once.", "Derive pairwise/net balances and settle through additional auditable entries."], "pitfall": "Greedy debt simplification changes payment paths, not the underlying recorded expense history.", "minutes": 11, "references": [["Martin Fowler • patterns", "https://martinfowler.com/tags/design.html"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Splitwise%2C%20cab%20booking%20%26%20concurrency-safe%20utilities%20explained%20computer%20science", "takeaway": "Greedy debt simplification changes payment paths, not the underlying recorded expense history."}, {"id": "linux-cli-git-reproducible-builds", "module": "devops", "title": "Linux CLI, Git & reproducible builds", "level": "Foundation", "concept": "Linux tools help inspect processes, files, permissions, sockets, logs, and resource use. Learn pipes and exit codes without exposing credentials in shell history. Git records source history through commits and branches; review diffs before staging, keep changes focused, and understand merge versus rebase. Package-manager lockfiles pin dependency resolution for reproducibility.", "deep": "A build should start from a known source revision and declared toolchain/dependencies, producing an identifiable artifact. Separate configuration from secrets and never commit credentials. CI should run relevant checks on the same source being packaged. File permissions, signals, and process exit behavior become deployment concerns once a service runs outside an IDE.", "examples": ["Use a process/socket inspection to confirm whether a service listens on the expected interface and port.", "CI installs from a lockfile, runs tests, and tags the resulting artifact with its source commit."], "nodes": ["Source revision", "Locked dependencies", "Checks", "Artifact"], "steps": ["Select an exact commit and inspect the diff.", "Install the declared dependency graph with an appropriate reproducible mode.", "Run checks that exercise the changed behavior and fail on meaningful errors.", "Build and identify the artifact so deployment can trace back to source."], "pitfall": "A passing local run with untracked files is not evidence that a clean checkout builds.", "minutes": 10, "references": [["Docker documentation", "https://docs.docker.com/"], ["Kubernetes concepts", "https://kubernetes.io/docs/concepts/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Linux%20CLI%2C%20Git%20%26%20reproducible%20builds%20explained%20computer%20science", "takeaway": "A passing local run with untracked files is not evidence that a clean checkout builds."}, {"id": "docker-images-containers-volumes-compose", "module": "devops", "title": "Docker images, containers, volumes & Compose", "level": "Foundation", "concept": "An image packages filesystem layers and startup metadata; a container is an isolated running instance using an image. Containers share the host kernel rather than booting a full guest OS. Volumes persist selected data outside a container’s writable layer. Container networking gives services explicit addressing and port publication; localhost inside a container refers to that container.", "deep": "A Dockerfile should pin sensible bases, avoid baking secrets into layers, run with least privilege, and handle termination. Multi-stage builds copy only necessary runtime output from build stages. Compose describes a local multi-service environment, but startup ordering does not guarantee a dependency is ready. Health checks, retries, resource limits, backups, and migrations remain application/operations responsibilities.", "examples": ["Compose starts an API and PostgreSQL; the API connects to the database service name rather than localhost.", "A multi-stage image compiles assets in one stage and ships only static output in a small runtime image."], "nodes": ["Dockerfile", "Build image", "Run container", "Mounted volume"], "steps": ["Declare a repeatable build without embedding secrets.", "Build immutable layers and tag/digest the resulting image.", "Start a container with runtime configuration, scoped permissions, and published ports.", "Persist required state through volumes and manage backups separately."], "pitfall": "Deleting a container should not be your data-retention policy, and a volume is not a backup.", "minutes": 11, "references": [["Docker documentation", "https://docs.docker.com/"], ["Kubernetes concepts", "https://kubernetes.io/docs/concepts/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Docker%20images%2C%20containers%2C%20volumes%20%26%20Compose%20explained%20computer%20science", "takeaway": "Deleting a container should not be your data-retention policy, and a volume is not a backup."}, {"id": "aws-iam-vpc-kubernetes-basics", "module": "devops", "title": "AWS, IAM, VPC & Kubernetes basics", "level": "Intermediate", "concept": "Cloud services solve different layers: EC2 runs virtual machines, S3 stores objects, RDS manages relational databases, Lambda runs event-driven functions, SQS queues work, and CloudFront distributes content. IAM controls permissions; VPC networking controls connectivity. Authentication permissions and network reachability are separate checks.", "deep": "Kubernetes schedules containerized workloads through pods, deployments, services, and configuration resources. Readiness controls traffic eligibility; liveness can restart unhealthy processes. Resource requests/limits and autoscaling need measured workloads. Managed platforms can reduce operational burden; do not add Kubernetes only to host one simple API. Keep databases private where appropriate and use least-privilege workload identities rather than long-lived keys in source.", "examples": ["An API on EC2 uses an IAM role to write only to its designated S3 prefix.", "A Kubernetes deployment runs three stateless replicas behind a service and removes an unready pod from routing."], "nodes": ["Client edge", "Application network", "Private database", "IAM check"], "steps": ["Accept traffic only at intended public entry points.", "Route to application workloads through controlled network paths.", "Allow database access from approved application identities/networks.", "Authorize each cloud action with least-privilege IAM in addition to network rules."], "pitfall": "Private networking does not replace authentication, encryption, backups, or IAM scoping.", "minutes": 10, "references": [["Docker documentation", "https://docs.docker.com/"], ["Kubernetes concepts", "https://kubernetes.io/docs/concepts/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=AWS%2C%20IAM%2C%20VPC%20%26%20Kubernetes%20basics%20explained%20computer%20science", "takeaway": "Private networking does not replace authentication, encryption, backups, or IAM scoping."}, {"id": "ci-cd-nginx-rollout-strategies-terraform", "module": "devops", "title": "CI/CD, Nginx, rollout strategies & Terraform", "level": "Intermediate", "concept": "CI validates changes; delivery prepares releasable artifacts; deployment moves a selected artifact into an environment. Nginx can terminate TLS, route traffic, serve static content, and proxy requests with explicit timeout and buffering settings. Rolling deployment gradually replaces instances; blue-green switches between two environments; canary exposes a small traffic fraction before wider rollout.", "deep": "Changes must remain compatible while old and new versions coexist. Use expand-and-contract database migrations, health checks, and rollback plans that account for data changes. Terraform declares infrastructure state and plans changes, but state storage, locking, credentials, and review still need management. Monitor user-facing error and latency signals during rollout rather than treating process startup as success.", "examples": ["Canary sends 5% of traffic to a new version and stops expansion if errors increase.", "Add a nullable column first, deploy code that tolerates both schemas, backfill, then enforce the final constraint later."], "nodes": ["Validated artifact", "Deploy small slice", "Observe SLIs", "Expand / rollback"], "steps": ["Select the exact checked artifact and compatible configuration.", "Deploy to a limited portion with readiness verification.", "Compare error, latency, and business signals against the baseline.", "Expand only when acceptable or revert through the prepared recovery path."], "pitfall": "Rolling back code may not roll back an incompatible database migration or an external side effect.", "minutes": 10, "references": [["Docker documentation", "https://docs.docker.com/"], ["Kubernetes concepts", "https://kubernetes.io/docs/concepts/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=CI/CD%2C%20Nginx%2C%20rollout%20strategies%20%26%20Terraform%20explained%20computer%20science", "takeaway": "Rolling back code may not roll back an incompatible database migration or an external side effect."}, {"id": "unit-integration-e2e-useful-mocks", "module": "testing", "title": "Unit, integration, E2E & useful mocks", "level": "Foundation", "concept": "Unit tests exercise a small behavior in isolation; integration tests validate boundaries such as database transactions or broker interactions; end-to-end tests exercise a complete user flow. Mocks replace dependencies but can drift from reality, so prefer contract checks and real integration coverage where semantics matter. TDD is a development loop, not a substitute for choosing meaningful assertions.", "deep": "Test observable invariants and failure cases instead of restating implementation lines. Financial transfers need rollback and concurrent-duplicate coverage; a simple reversible text change may only need inspection. Load tests examine capacity and tails separately from functional correctness. Keep fixtures deterministic and avoid production credentials/data. A small focused test suite that catches realistic failures is more valuable than a high coverage number alone.", "examples": ["Unit: reject a negative order quantity before calling the repository.", "Integration: submit the same payment operation concurrently and assert one committed ledger effect."], "nodes": ["Arrange state", "Trigger behavior", "Observe result", "Check invariant"], "steps": ["Create controlled inputs and dependencies.", "Execute the public operation including the failure condition being tested.", "Read returned behavior and relevant persisted effects.", "Assert the invariant, such as no partial transfer, rather than private implementation details."], "pitfall": "A mocked database cannot prove SQL locking, constraints, or transaction isolation behavior.", "minutes": 11, "references": [["OpenTelemetry concepts", "https://opentelemetry.io/docs/concepts/"], ["Prometheus practices", "https://prometheus.io/docs/practices/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Unit%2C%20integration%2C%20E2E%20%26%20useful%20mocks%20explained%20computer%20science", "takeaway": "A mocked database cannot prove SQL locking, constraints, or transaction isolation behavior."}, {"id": "structured-logs-metrics-health-alerting", "module": "testing", "title": "Structured logs, metrics, health & alerting", "level": "Intermediate", "concept": "Logs describe discrete events, metrics aggregate numerical signals, and health checks expose selected readiness or liveness conditions. Structured logs use named fields such as request_id and operation rather than text parsing. Prometheus collects time-series metrics; Grafana visualizes them; ELK-style stacks index and search logs. These tools need a deliberate signal design.", "deep": "Use low-cardinality metric labels, redact secrets, and keep correlation identifiers in logs/traces where appropriate. Readiness should reflect ability to serve traffic without cascading instability; liveness should not restart a process merely because a dependency is temporarily slow. Alert on actionable user impact and sustained error-budget burn rather than every individual exception. Define an owner and recovery action for each alert.", "examples": ["A counter tracks failed checkouts by stable error class while request IDs remain in logs.", "An API is live but unready during startup until it can safely accept its expected traffic."], "nodes": ["Application event", "Structured log", "Aggregated metric", "Actionable alert"], "steps": ["Classify an operation outcome and attach safe correlation context.", "Write a structured record without passwords or full credentials.", "Update bounded-cardinality latency/error metrics.", "Trigger an alert from sustained user impact with a clear diagnostic path."], "pitfall": "Unbounded labels such as user ID or raw URL can overwhelm a metrics system.", "minutes": 11, "references": [["OpenTelemetry concepts", "https://opentelemetry.io/docs/concepts/"], ["Prometheus practices", "https://prometheus.io/docs/practices/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Structured%20logs%2C%20metrics%2C%20health%20%26%20alerting%20explained%20computer%20science", "takeaway": "Unbounded labels such as user ID or raw URL can overwhelm a metrics system."}, {"id": "traces-spans-service-maps-latency-breakdown", "module": "testing", "title": "Traces, spans, service maps & latency breakdown", "level": "Intermediate", "concept": "A trace follows one logical operation across components; spans represent timed units with parent/child or linked relationships. Context propagation connects downstream work without relying on coincident timestamps. OpenTelemetry standardizes instrumentation and telemetry transport; backends such as Jaeger or compatible APM systems store and inspect traces. A service map derives observed call relationships, not a complete architecture specification.", "deep": "Capture database, network, serialization, and queue-wait boundaries without recording secrets. Async jobs may need links or explicit propagation and separate queue-wait timing. Sampling controls cost but can hide rare events; design error/tail sampling deliberately where supported. Do not sum overlapping child durations as if all work were serial. Use traces to form a hypothesis and validate with workload measurements.", "examples": ["A 200 ms request contains a 150 ms database span, making SQL the first investigation target.", "Two parallel 100 ms HTTP spans do not imply a 200 ms parent duration; they overlap."], "nodes": ["Root request span", "Propagate context", "Database/worker spans", "Trace viewer"], "steps": ["Start or accept a trace with an appropriate trust boundary.", "Send context to authorized downstream services or queued work.", "Record useful child/link spans and errors with safe attributes.", "Inspect the waterfall and distinguish critical-path work from parallel or queued time."], "pitfall": "Tracing is observational evidence; missing or sampled spans do not prove a dependency was never called.", "minutes": 11, "references": [["OpenTelemetry concepts", "https://opentelemetry.io/docs/concepts/"], ["Prometheus practices", "https://prometheus.io/docs/practices/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Traces%2C%20spans%2C%20service%20maps%20%26%20latency%20breakdown%20explained%20computer%20science", "takeaway": "Tracing is observational evidence; missing or sampled spans do not prove a dependency was never called."}, {"id": "e-commerce-backend-project", "module": "projects", "title": "E-commerce backend project", "level": "Project", "concept": "Build auth, catalog, orders, inventory, and mock payments before adding distributed components. The core invariant is one accepted order transition with no negative inventory or duplicate payment effect. Keep a modular design and a documented REST contract.", "deep": "Start with PostgreSQL transactions, conditional inventory updates, and unique operation keys. Add an order saga only across genuinely separate boundaries, using a mock provider with controllable failures. Include migrations, integration checks for concurrent checkout, and a deployment runbook.", "examples": ["Checkout succeeds: stock decreases once and the mock payment is recorded.", "Payment fails after reservation: the saga releases inventory and records cancellation."], "nodes": ["Cart request", "Reserve stock", "Mock payment", "Confirm/compensate"], "steps": ["Validate the cart, caller, and idempotency key.", "Reserve inventory using guarded local updates.", "Call a mock payment provider with the same stable operation identity.", "Confirm on success or run observable idempotent compensation on failure."], "pitfall": "Do not use real payment credentials or claim production financial guarantees for a mock project.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=E-commerce%20backend%20project%20explained%20computer%20science", "takeaway": "Do not use real payment credentials or claim production financial guarantees for a mock project."}, {"id": "url-shortener-redis-analytics-project", "module": "projects", "title": "URL shortener + Redis analytics project", "level": "Project", "concept": "Build create and redirect endpoints, durable mappings, expiry, a Redis cache, and asynchronous click analytics. Document the redirect contract and cache freshness. Measure cold and warm paths under the same request mix.", "deep": "Add unique code generation, input validation, abuse controls, a bounded analytics queue, and a simple dashboard. Show what happens when Redis fails or analytics is unavailable: redirects should follow the intended degradation policy. Package with Compose and a reproducible seed dataset.", "examples": ["A hot link is served from cache without a database lookup.", "Cache outage falls back to storage under a bounded concurrency policy."], "nodes": ["Create mapping", "Redirect lookup", "Redis hit/miss", "Analytics queue"], "steps": ["Persist a validated link with a unique code and expiry.", "Accept a request for the code and enforce deletion/expiry policy.", "Read through the cache-aside path and return the redirect.", "Publish a bounded asynchronous click event for later aggregation."], "pitfall": "Do not make redirects wait synchronously for noncritical analytics writes.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=URL%20shortener%20%2B%20Redis%20analytics%20project%20explained%20computer%20science", "takeaway": "Do not make redirects wait synchronously for noncritical analytics writes."}, {"id": "websocket-chat-project", "module": "projects", "title": "WebSocket chat project", "level": "Project", "concept": "Build authenticated conversations, persistent messages, reconnect history, and separate delivery/read receipts. Start with one server and add a second instance only when the single-instance model is correct. Explicitly define conversation ordering and message IDs.", "deep": "Persist before acknowledging accepted messages, deduplicate retries, and use a resume cursor. Add shared pub/sub for cross-instance live fan-out while retaining database history as the recovery path. Test a dropped socket, worker restart, and a slow client. Keep presence approximate and exclude private content from logs.", "examples": ["A client reconnects after receiving message 20 and fetches 21 onward.", "Two replicas route a message to devices connected to different servers."], "nodes": ["Authenticated socket", "Persist once", "Fan-out", "Reconnect history"], "steps": ["Check membership for every send/subscribe action.", "Save the message with a unique client operation ID.", "Publish to connected recipients and manage bounded buffers.", "On reconnect load missed durable history using a stable cursor."], "pitfall": "Pub/sub messages may be lost during disconnection; durable history is the recovery source.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=WebSocket%20chat%20project%20explained%20computer%20science", "takeaway": "Pub/sub messages may be lost during disconnection; durable history is the recovery source."}, {"id": "fastapi-celery-redis-job-queue-project", "module": "projects", "title": "FastAPI + Celery + Redis job queue project", "level": "Project", "concept": "Create a job API that responds quickly with an ID while Celery workers perform a simulated slow computation. Store authoritative job state and publish progress through SSE. The demo should distinguish queued time, running time, completed, failed, and cancelled states.", "deep": "Use separate broker and result/state responsibilities, bounded worker concurrency, task idempotency, time limits, and capped retries. Reconnect SSE from retained events or return a status snapshot. Run API, worker, Redis, and state storage through Compose, then demonstrate worker-crash recovery.", "examples": ["A 30-second report returns 202 immediately and streams stage progress.", "A worker dies before ack; redelivery does not create a second final report."], "nodes": ["POST job", "Celery broker", "Worker + state", "SSE progress"], "steps": ["Create a durable job identity and enqueue work reliably.", "Return 202 and a status/stream URL.", "The worker executes bounded stages and records progress/results.", "The browser follows SSE, resumes or snapshots after reconnect, and renders the terminal state."], "pitfall": "Redis pub/sub alone is not a durable job state store or replay log.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=FastAPI%20%2B%20Celery%20%2B%20Redis%20job%20queue%20project%20explained%20computer%20science", "takeaway": "Redis pub/sub alone is not a durable job state store or replay log."}, {"id": "resilient-scraper-project", "module": "projects", "title": "Resilient scraper project", "level": "Project", "concept": "Implement an allowed-domain ingestion pipeline with rate limits, timeouts, backoff, change detection, and checkpoint/resume. Prefer ordinary HTTP and official APIs; use browser automation only when the permitted task requires it. Keep crawl scope and policy visible.", "deep": "Queue jobs per domain, classify 429/403/network/layout failures, and isolate unhealthy destinations with circuit breakers. Proxy health management can support permitted routing but must not bypass restrictions. Demonstrate crash recovery, unchanged-page skipping, and bounded browser resources.", "examples": ["An unchanged content hash avoids duplicate indexing on the next scheduled run.", "A 429 applies a domain cooldown while other permitted domains continue."], "nodes": ["Allowed URL", "Domain budget", "Fetch + parse", "Checkpoint/dedupe"], "steps": ["Verify scope and load the last successful checkpoint.", "Wait for the domain’s permitted concurrency/rate budget.", "Fetch with bounded waits and classify the outcome.", "Store changed content and progress idempotently for resumable runs."], "pitfall": "Do not treat access controls, CAPTCHAs, or site restrictions as obstacles to defeat.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Resilient%20scraper%20project%20explained%20computer%20science", "takeaway": "Do not treat access controls, CAPTCHAs, or site restrictions as obstacles to defeat."}, {"id": "rate-limiter-or-mini-key-value-store-project", "module": "projects", "title": "Rate limiter or mini key-value store project", "level": "Project", "concept": "Choose one infrastructure primitive and define its contract precisely. A limiter needs rate, burst, identity, and clock semantics. A mini key-value store needs key/value bounds, TTL, update behavior, and optionally durability. Keep the first implementation small enough to reason about.", "deep": "For a limiter, build a deterministic-clock token bucket and test boundary bursts and concurrent admission. For a store, start with a bounded map and add log/recovery only if promising durability. Compare behavior under load, report complexity, and explain failure limits rather than claiming production readiness.", "examples": ["A five-token bucket admits five immediate requests and rejects the sixth until refill.", "A TTL key disappears after the defined deadline in a test using an injected clock."], "nodes": ["Define contract", "Implement primitive", "Exercise boundaries", "Measure/report"], "steps": ["Write the exact API and its invariants.", "Build the simplest implementation that meets the stated scope.", "Test concurrent requests, time boundaries, and capacity exhaustion.", "Measure throughput/latency and document what failures the design does and does not survive."], "pitfall": "A benchmark alone does not prove correctness under crashes, races, or clock changes.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Rate%20limiter%20or%20mini%20key-value%20store%20project%20explained%20computer%20science", "takeaway": "A benchmark alone does not prove correctness under crashes, races, or clock changes."}, {"id": "deploy-a-backend-with-docker-ci-cd", "module": "projects", "title": "Deploy a backend with Docker & CI/CD", "level": "Project", "concept": "Take one completed project through a reproducible build and a real deployment using a chosen provider. Ship configuration documentation, health endpoints, database migration steps, a rollback plan, and a small public API specification. Deployment should make the system inspectable, not merely reachable.", "deep": "CI should check the exact revision, build an identifiable artifact, and avoid leaking secrets. Configure least-privilege credentials, TLS, bounded timeouts, logs/metrics, and backups where state is persistent. Demonstrate a safe release and a controlled failure, then explain recovery and resource cost assumptions in the README.", "examples": ["A new API version rolls out gradually while old and new code both tolerate the database schema.", "A failed readiness check prevents a broken instance from receiving traffic."], "nodes": ["Push source", "CI build/check", "Deploy artifact", "Observe & recover"], "steps": ["Select the reviewed revision and pinned dependencies.", "Run meaningful checks and produce a traceable image/artifact.", "Apply compatible migrations and deploy with readiness verification.", "Observe errors/latency and practice the documented rollback or recovery."], "pitfall": "Do not store secrets in images, source, frontend bundles, or CI logs.", "minutes": 9, "references": [["FastAPI tutorial", "https://fastapi.tiangolo.com/tutorial/"], ["Docker getting started", "https://docs.docker.com/get-started/"]], "video": null, "searchVideo": "https://www.youtube.com/results?search_query=Deploy%20a%20backend%20with%20Docker%20%26%20CI/CD%20explained%20computer%20science", "takeaway": "Do not store secrets in images, source, frontend bundles, or CI logs."}]};